  <title>Snake</title>
  <style>
    :root { --bg: #052e16; --panel: #14532d; --text: #ecfdf5; --muted: #86efac; --accent: #facc15; }
    *, *::before, *::after { box-sizing: border-box; }
    body {
      margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 1rem;
