  <script>
    const STORAGE_KEY = 'kalkulator-ilmiah';
    const MAX_HISTORY = 20;
    const exprEl = document.getElementById('expr');
    const resultEl = document.getElementById('result');
    const angleBtn = document.getElementById('angle');
    const listEl = document.getElementById('history-list');

    let useDegrees = true;
    let ans = 0;
    let history = [];

    const load = () => { try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || {}; } catch (e) { return {}; } };
    const save = () => { try { localStorage.setItem(STORAGE_KEY, JSON.stringify({ history, ans, useDegrees })); } catch (e) { /* mode privat */ } };

    // ---------- Tokenizer ----------
    const FUNCS = ['sin', 'cos', 'tan', 'ln', 'log', 'sqrt', '√'];
    function tokenize(src) {
      const s = src.replace(/\s+/g, '').replace(/[×*]/g, '*').replace(/[÷/:]/g, '/').replace(/[−–]/g, '-');
      const tokens = [];
      let i = 0;
      while (i < s.length) {
        const rest = s.slice(i);
        const num = rest.match(/^(\d+[.,]?\d*|[.,]\d+)/);
        if (num) { tokens.push({ type: 'num', value: parseFloat(num[0].replace(',', '.')) }); i += num[0].length; continue; }
        const word = rest.match(/^(sqrt|sin|cos|tan|ln|log|ans|pi|π|√|e)/i);
        if (word) {
          const w = word[0].toLowerCase();
          if (w === 'pi' || w === 'π') tokens.push({ type: 'num', value: Math.PI });
          else if (w === 'e') tokens.push({ type: 'num', value: Math.E });
          else if (w === 'ans') tokens.push({ type: 'num', value: ans });
          else tokens.push({ type: 'func', value: w === 'sqrt' ? '√' : w });
          i += w.length; continue;
        }
        if ('+-*/^()!%'.includes(s[i])) { tokens.push({ type: 'op', value: s[i] }); i++; continue; }
        throw new Error(`Karakter "${s[i]}" tidak dikenal`);
      }
      return tokens;
    }

    // ---------- Parser recursive descent (tanpa eval) ----------
    // expr := term (+|- term)* ; term := unary (*|/ unary | perkalian implisit)*
    // unary := (+|-) unary | power ; power := postfix (^ unary)?  → 2^3^2 = 2^9, -2^2 = -4
    function parse(tokens) {
      let pos = 0;
      const peek = () => tokens[pos];
      const isOp = (v) => peek() && peek().type === 'op' && peek().value === v;
      const startsOperand = () => peek() && (peek().type !== 'op' || peek().value === '(');

      function expr() {
        let v = term();
        while (isOp('+') || isOp('-')) v = tokens[pos++].value === '+' ? v + term() : v - term();
        return v;
      }
      function term() {
        let v = unary();
        for (;;) {
          if (isOp('*')) { pos++; v *= unary(); }
          else if (isOp('/')) {
            pos++;
            const d = unary();
            if (d === 0) throw new Error('Tidak bisa dibagi nol');
            v /= d;
          } else if (startsOperand()) v *= power(); // 2π, 3(4+1), 2sin(30)
          else return v;
        }
      }
      function unary() {
        if (isOp('-')) { pos++; return -unary(); }
        if (isOp('+')) { pos++; return unary(); }
        return power();
      }
      function power() {
        const base = postfix();
        if (isOp('^')) { pos++; return Math.pow(base, unary()); }
        return base;
      }
      function postfix() {
        let v = primary();
        while (isOp('!') || isOp('%')) v = tokens[pos++].value === '!' ? factorial(v) : v / 100;
        return v;
      }
      function primary() {
        const t = tokens[pos++];
        if (!t) throw new Error('Ekspresi belum lengkap');
        if (t.type === 'num') return t.value;
        if (t.type === 'func') return applyFunc(t.value, t.value === '√' && !isOp('(') ? power() : primary());
        if (t.value === '(') {
          const v = expr();
          if (isOp(')')) pos++; // kurung tutup di akhir boleh dilupakan, seperti kalkulator HP
          else if (peek()) throw new Error('Kurung tidak seimbang');
          return v;
        }
        throw new Error(`"${t.value}" tidak di tempat yang benar`);
      }

      const value = expr();
      if (pos < tokens.length) throw new Error(tokens[pos].value === ')' ? 'Kurung tidak seimbang' : 'Ekspresi tidak valid');
      return value;
    }

    function factorial(n) {
      if (!Number.isInteger(n) || n < 0) throw new Error('Faktorial hanya untuk bilangan bulat ≥ 0');
      if (n > 170) throw new Error('Hasil terlalu besar');
      let r = 1;
      for (let i = 2; i <= n; i++) r *= i;
      return r;
    }

    const snap = (v) => (Math.abs(v) < 1e-12 ? 0 : v); // sin(180°) = 0, bukan 1,2e-16
    function applyFunc(name, x) {
      const rad = useDegrees ? x * Math.PI / 180 : x;
      switch (name) {
        case 'sin': return snap(Math.sin(rad));
        case 'cos': return snap(Math.cos(rad));
        case 'tan':
          if (Math.abs(Math.cos(rad)) < 1e-12) throw new Error('tan tidak terdefinisi di sudut ini');
          return snap(Math.tan(rad));
        case 'ln': if (x <= 0) throw new Error('ln hanya untuk bilangan > 0'); return Math.log(x);
        case 'log': if (x <= 0) throw new Error('log hanya untuk bilangan > 0'); return Math.log10(x);
        case '√': if (x < 0) throw new Error('Akar dari bilangan negatif'); return Math.sqrt(x);
      }
    }

    function calculate(src) {
      const tokens = tokenize(src);
      if (!tokens.length) throw new Error('Ekspresi kosong');
      const v = parse(tokens);
      if (!Number.isFinite(v)) throw new Error('Hasil di luar jangkauan');
      return v;
    }

    const plain = new Intl.NumberFormat('id-ID', { maximumSignificantDigits: 12 });
    const sci = new Intl.NumberFormat('id-ID', { notation: 'scientific', maximumSignificantDigits: 10 });
    function format(v) {
      const a = Math.abs(v);
      if (a !== 0 && (a >= 1e15 || a < 1e-9)) return sci.format(v).replace('E', ' × 10^');
      return plain.format(v).replace('-', '−');
    }

    // ---------- UI ----------
    function showResult(text, kind) {
      resultEl.textContent = text;
      resultEl.className = kind || '';
    }

    function preview() {
      const src = exprEl.value.trim();
      if (!src) return showResult('');
      try { showResult('= ' + format(calculate(src)), 'preview'); } catch (e) { showResult(''); }
    }

    function equals() {
      const src = exprEl.value.trim();
      if (!src) return;
      try {
        const v = calculate(src);
        ans = v;
        showResult(format(v));
        history.unshift({ expr: src, result: format(v) });
        history = history.slice(0, MAX_HISTORY);
        save();
        renderHistory();
        document.getElementById('ans-label').textContent = 'Ans = ' + format(ans);
      } catch (e) {
        showResult(e.message, 'error');
      }
    }

    function insert(text) {
      const start = exprEl.selectionStart ?? exprEl.value.length;
      const end = exprEl.selectionEnd ?? exprEl.value.length;
      exprEl.setRangeText(text, start, end, 'end');
      preview();
    }

    function backspace() {
      let start = exprEl.selectionStart ?? exprEl.value.length;
      const end = exprEl.selectionEnd ?? start;
      if (start === end) {
        // hapus nama fungsi sekaligus, misalnya "sin(" atau "Ans"
        const before = exprEl.value.slice(0, start);
        const m = before.match(/(sqrt\(|sin\(|cos\(|tan\(|log\(|ln\(|√\(|Ans|.)$/);
        start -= m ? m[0].length : 0;
      }
      exprEl.setRangeText('', Math.max(0, start), end, 'end');
      preview();
    }

    function renderHistory() {
      listEl.replaceChildren();
      history.forEach((h) => {
        const li = document.createElement('li');
        const btn = document.createElement('button');
        btn.type = 'button';
        const e = document.createElement('span');
        e.className = 'h-expr';
        e.textContent = h.expr;
        const r = document.createElement('span');
        r.className = 'h-res';
        r.textContent = '= ' + h.result;
        btn.append(e, r);
        btn.addEventListener('click', () => { exprEl.value = h.expr; exprEl.focus(); preview(); });
        li.append(btn);
        listEl.append(li);
      });
      document.getElementById('history-empty').hidden = history.length > 0;
    }

    function setAngle(deg) {
      useDegrees = deg;
      angleBtn.textContent = deg ? 'DEG' : 'RAD';
      angleBtn.setAttribute('aria-pressed', String(deg));
      document.getElementById('mode-label').textContent = 'Mode: ' + (deg ? 'derajat' : 'radian');
      save();
      preview();
    }

    document.getElementById('keys').addEventListener('click', (e) => {
      const key = e.target.closest('.key');
      if (!key || key === angleBtn) return;
      if (key.dataset.insert) insert(key.dataset.insert);
      else if (key.dataset.action === 'clear') { exprEl.value = ''; showResult(''); }
      else if (key.dataset.action === 'backspace') backspace();
      else if (key.dataset.action === 'equals') equals();
      if (matchMedia('(pointer: fine)').matches) exprEl.focus();
    });
    angleBtn.addEventListener('click', () => setAngle(!useDegrees));
    exprEl.addEventListener('input', preview);
    exprEl.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === '=') { e.preventDefault(); equals(); }
      else if (e.key === 'Escape') { exprEl.value = ''; showResult(''); }
    });
    document.getElementById('clear-history').addEventListener('click', () => { history = []; save(); renderHistory(); });

    const saved = load();
    history = Array.isArray(saved.history) ? saved.history.slice(0, MAX_HISTORY) : [];
    ans = Number.isFinite(saved.ans) ? saved.ans : 0;
    document.getElementById('ans-label').textContent = 'Ans = ' + format(ans);
    setAngle(saved.useDegrees !== false);
    renderHistory();
    exprEl.focus();
  </script>
</body>
</html>
```

**Cek kebutuhan**
- **sin, cos, tan** → `applyFunc()`. Di mode derajat, sudut diubah ke radian lebih dulu. Hasil yang sangat dekat dengan nol dibulatkan ke 0, jadi `cos(90)` tampil `0`, dan `tan(90)` ditolak dengan pesan "tidak terdefinisi".
- **log dan ln** → `Math.log10` dan `Math.log`, dengan pesan error untuk bilangan ≤ 0.
- **Akar, pangkat, faktorial** → tombol `√`, `x²`, `xʸ`, dan `n!`.
  - Pangkat dihitung dari kanan (`2^3^2 = 512`).
  - Pangkat lebih kuat dari tanda minus (`-2^2 = −4`), sama seperti kalkulator ilmiah pada umumnya.
  - Faktorial hanya untuk bilangan bulat 0–170.
- **Kurung** → ditangani `primary()`. Kurung tutup terakhir boleh tidak ditulis. Perkalian tanpa tanda `×` seperti `2π` atau `(1+2)(3+4)` juga didukung.
- **π dan e** → masing-masing punya tombol. π juga bisa diketik sebagai `pi`.
- **Derajat atau radian** → tombol `DEG/RAD` dengan `aria-pressed`, dan pilihannya ikut tersimpan.
- **Riwayat yang bisa diklik** → `renderHistory()` menyimpan 20 perhitungan terakhir di `localStorage`. Klik salah satunya untuk memuat ulang ekspresinya. Hasil terakhir bisa dipakai lagi lewat tombol `Ans`.
- **Tanpa `eval`** → `tokenize()` hanya menerima angka, operator, dan nama fungsi yang dikenal. Karakter lain langsung ditolak.

**Detail**
- Hasil memakai format Indonesia (`1.234.567`, `0,5`) dan dibulatkan ke 12 angka penting, jadi `0,1 + 0,2` tampil `0,3`. Angka yang sangat besar atau sangat kecil ditampilkan dalam notasi ilmiah.
- Desimal boleh diketik dengan koma atau titik, sehingga saat mengetik titik tidak berfungsi sebagai pemisah ribuan.
- `%` membagi angka di depannya dengan 100, jadi `50%` = `0,5`.

