    .cart { list-style: none; margin: 0; padding: 0; max-height: 300px; overflow-y: auto; }
    .cart li { display: flex; flex-wrap: wrap; justify-content: space-between; gap: .3rem; padding: .5rem 0; border-bottom: 1px solid var(--line); }
    .cart small { display: block; color: var(--muted); }
    .qty { display: flex; gap: .3rem; align-items: center; width: 100%; justify-content: flex-end; }
    .qty button { width: 30px; height: 30px; border: 1px solid #cbd5e1; border-radius: 6px; background: #fff; }
    .totals { margin: .75rem 0; font-variant-numeric: tabular-nums; }
    .totals div, .change { display: flex; justify-content: space-between; padding: .15rem 0; }
    .totals .grand { font-size: 1.35rem; font-weight: 800; border-top: 2px solid var(--text); padding-top: .4rem; }
    .chips { display: flex; flex-wrap: wrap; gap: .4rem; margin: .5rem 0; }
    .chip { border: 1px solid #99f6e4; background: #f0fdfa; color: var(--dark); border-radius: 999px; padding: .3rem .7rem; font-size: .85rem; }
    .change { font-weight: 700; font-size: 1.1rem; }
    .change.short { color: var(--danger); }
    .btn { width: 100%; border: 0; border-radius: 10px; padding: .8rem; font-weight: 700; background: var(--primary); color: #fff; }
    .btn:disabled { background: #94a3b8; cursor: not-allowed; }
    .btn.secondary { background: #e2e8f0; color: var(--text); }
    .setting { display: flex; gap: .5rem; font-size: .85rem; color: var(--muted); margin-top: .75rem; }
    .report { grid-column: 1 / -1; }
    .stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: .6rem; margin-bottom: 1rem; }
    .stats div { background: #f8fafc; border-radius: 10px; padding: .6rem .8rem; }
    .stats span { display: block; font-size: .8rem; color: var(--muted); }
