    dialog { border: 0; border-radius: 12px; padding: 1rem; width: min(360px, 94vw); }
    #receipt { font: 12px/1.45 ui-monospace, Consolas, monospace; white-space: pre; margin: 0 0 .75rem; padding: .75rem; border: 1px dashed #cbd5e1; overflow-x: auto; }
    .actions { display: flex; gap: .5rem; }
    @media (max-width: 860px) { main { grid-template-columns: minmax(0, 1fr); } }
