    :root { --bg: #faf6f1; --text: #2b1d14; --muted: #7c6a5d; --brand: #7c2d12; --brand-2: #9a3412; --line: #eadfd4; --ok: #166534; --danger: #b91c1c; }
    *, *::before, *::after { box-sizing: border-box; }
    body { margin: 0; background: var(--bg); color: var(--text); font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }
    header { background: var(--brand); color: #fff; padding: .8rem 1rem; }
