  </style>
</head>
<body>
  <header><h1>Kasir Kafe Senja <small style="font-weight:400">(simulasi)</small></h1></header>
  <main>
    <section class="card" aria-labelledby="menu-title">
      <h2 id="menu-title">Menu</h2>
      <div class="tabs" role="tablist" id="tabs"></div>
      <div class="menu" id="menu" role="tabpanel"></div>
    </section>

    <section class="card" aria-labelledby="order-title">
      <h2 id="order-title">Pesanan baru</h2>
      <div class="seg" id="type" aria-label="Jenis pesanan">
        <button type="button" data-type="dine" aria-pressed="true">Makan di tempat</button>
        <button type="button" data-type="take" aria-pressed="false">Bawa pulang</button>
      </div>
      <div id="table-wrap"><label for="table">Nomor meja</label> <input type="text" id="table" inputmode="numeric" maxlength="3" style="width:5rem"></div>
      <ul class="lines" id="lines"></ul>
      <p class="empty" id="lines-empty">Belum ada item. Klik menu untuk menambahkan.</p>
      <div class="sum">
        <div><span>Subtotal</span><span id="subtotal"></span></div>
        <div><span id="service-label"></span><span id="service"></span></div>
        <div><span id="tax-label"></span><span id="tax"></span></div>
        <div class="grand"><span>Total</span><span id="total"></span></div>
      </div>
      <h2 style="margin-top:1rem">Pembayaran</h2>
      <div class="seg" id="method" aria-label="Metode pembayaran">
        <button type="button" data-method="tunai" aria-pressed="true">Tunai</button>
        <button type="button" data-method="qris" aria-pressed="false">QRIS</button>
        <button type="button" data-method="debit" aria-pressed="false">Kartu debit</button>
      </div>
      <div id="cash-wrap">
        <label for="cash">Uang diterima</label>
        <input type="text" id="cash" inputmode="numeric" autocomplete="off">
        <p class="muted" id="change"></p>
      </div>
      <p class="muted" id="noncash-info" hidden>Simulasi: tekan konfirmasi setelah pembayaran berhasil di aplikasi atau mesin EDC.</p>
      <p class="msg" id="msg" aria-live="polite"></p>
      <button type="button" class="pay" id="pay" disabled>Bayar</button>
      <p id="toast" aria-live="polite"></p>
      <details>
        <summary>Pengaturan pajak &amp; service</summary>
        <div class="row">
          <div><label for="set-service">Service (%), makan di tempat</label><input type="number" id="set-service" min="0" max="20" step="0.5"></div>
          <div><label for="set-tax">Pajak resto/PBJT (%)</label><input type="number" id="set-tax" min="0" max="10" step="0.5"></div>
        </div>
      </details>
    </section>

    <section class="card queue" aria-labelledby="queue-title">
      <h2 id="queue-title">Antrean dapur hari ini</h2>
      <div class="cols" id="queue"></div>
    </section>
  </main>

  <script>
    const STORAGE_KEY = 'kasir-kafe-v1';
    const MENU = {
      Kopi: [['Espresso', 18000], ['Americano', 22000], ['Kopi susu gula aren', 25000], ['Cappuccino', 28000]],
      'Non-kopi': [['Matcha latte', 30000], ['Cokelat panas', 27000], ['Teh tarik', 20000], ['Lemon tea', 18000]],
      Makanan: [['Croissant', 22000], ['Roti bakar', 20000], ['Nasi goreng kampung', 35000], ['Kentang goreng', 23000]],
    };
    const STATUS = [['diproses', 'Diproses', 'Tandai siap'], ['siap', 'Siap diambil', 'Selesai'], ['selesai', 'Selesai', '']];

    const $ = (id) => document.getElementById(id);
    const rp = (n) => 'Rp ' + n.toLocaleString('id-ID');
    const parseRp = (s) => parseInt(String(s).replace(/\D/g, ''), 10) || 0;
    const esc = (s) => String(s).replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
    const today = () => new Date().toLocaleDateString('en-CA'); // YYYY-MM-DD waktu lokal

    let data = { orders: [], service: 5, tax: 10 };
    try {
      const d = JSON.parse(localStorage.getItem(STORAGE_KEY));
      if (d && Array.isArray(d.orders)) data = { ...data, ...d };
    } catch (e) { /* mulai kosong */ }
    const save = () => { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); } catch (e) { $('msg').textContent = 'Data tidak bisa disimpan di browser ini.'; } };

    let category = 'Kopi';
    let order = { type: 'dine', method: 'tunai', lines: [] };

    function totals() {
      const subtotal = order.lines.reduce((a, l) => a + l.price * l.qty, 0);
      const service = order.type === 'dine' ? Math.round(subtotal * data.service / 100) : 0;
      // PBJT dihitung dari jumlah yang dibayar konsumen, jadi service charge ikut menjadi dasar pajak.
      const tax = Math.round((subtotal + service) * data.tax / 100);
      return { subtotal, service, tax, total: subtotal + service + tax };
    }

    function problem(t) {
      if (!order.lines.length) return 'Pesanan masih kosong.';
      if (order.type === 'dine' && !$('table').value.trim()) return 'Isi nomor meja untuk pesanan makan di tempat.';
      if (order.method === 'tunai' && parseRp($('cash').value) < t.total) return 'Uang tunai kurang dari total.';
      return '';
    }

    function render() {
      $('tabs').innerHTML = Object.keys(MENU).map((c) =>
        `<button type="button" class="tab" role="tab" data-cat="${c}" aria-selected="${c === category}">${c}</button>`).join('');
      $('menu').innerHTML = MENU[category].map(([name, price]) =>
        `<button type="button" data-add="${esc(name)}" data-price="${price}"><strong>${esc(name)}</strong><b>${rp(price)}</b></button>`).join('');

      $('lines').innerHTML = order.lines.map((l, i) => `<li><span>${esc(l.name)}<br><small class="muted">${rp(l.price * l.qty)}</small></span>
        <span class="qty"><button type="button" data-step="-1" data-line="${i}" aria-label="Kurangi ${esc(l.name)}">−</button>${l.qty}
        <button type="button" data-step="1" data-line="${i}" aria-label="Tambah ${esc(l.name)}">+</button></span>
        <input type="text" data-note="${i}" value="${esc(l.note)}" maxlength="60" placeholder="Catatan, mis. less sugar" aria-label="Catatan ${esc(l.name)}"></li>`).join('');
      $('lines-empty').hidden = order.lines.length > 0;
      document.querySelectorAll('#type button').forEach((b) => b.setAttribute('aria-pressed', b.dataset.type === order.type));
      document.querySelectorAll('#method button').forEach((b) => b.setAttribute('aria-pressed', b.dataset.method === order.method));
      $('table-wrap').hidden = order.type !== 'dine';
      $('cash-wrap').hidden = order.method !== 'tunai';
      $('noncash-info').hidden = order.method === 'tunai';
      updateTotals();

      const list = data.orders.filter((o) => o.date === today());
      $('queue').innerHTML = STATUS.map(([key, title, next]) => {
        const items = list.filter((o) => o.status === key).slice(key === 'selesai' ? -5 : 0);
        return `<div class="col"><h3>${title} (${list.filter((o) => o.status === key).length})</h3>${items.map((o) => `<div class="order" data-no="${o.no}">
          <strong>${o.no}</strong> · ${o.type === 'dine' ? `Meja ${esc(o.table)}` : 'Bawa pulang'}
          <ul>${o.lines.map((l) => `<li>${l.qty}× ${esc(l.name)}${l.note ? ` — <em>${esc(l.note)}</em>` : ''}</li>`).join('')}</ul>
          ${next ? `<button type="button" data-advance="${o.no}">${next}</button>` : ''}</div>`).join('') || '<p class="empty">Kosong</p>'}</div>`;
      }).join('');
    }

    function updateTotals() {
      const t = totals();
      $('subtotal').textContent = rp(t.subtotal);
      $('service-label').textContent = `Service ${data.service}%${order.type === 'dine' ? '' : ' (tidak untuk bawa pulang)'}`;
      $('service').textContent = rp(t.service);
      $('tax-label').textContent = `Pajak resto ${data.tax}%`;
      $('tax').textContent = rp(t.tax);
      $('total').textContent = rp(t.total);
      const cash = parseRp($('cash').value);
      $('change').textContent = cash ? (cash >= t.total ? `Kembalian ${rp(cash - t.total)}` : `Kurang ${rp(t.total - cash)}`) : '';
      $('pay').disabled = Boolean(problem(t));
      $('pay').textContent = order.method === 'tunai' ? `Bayar ${rp(t.total)}` : `Konfirmasi ${order.method === 'qris' ? 'QRIS' : 'debit'} ${rp(t.total)}`;
    }

    function pay() {
      const t = totals();
      const err = problem(t);
      $('msg').textContent = err;
      if (err) return;
      const seq = data.orders.filter((o) => o.date === today()).length + 1;
      const o = {
        no: 'A-' + String(seq).padStart(3, '0'), date: today(), time: new Date().toISOString(), status: 'diproses',
        type: order.type, table: order.type === 'dine' ? $('table').value.trim() : '', method: order.method,
        lines: order.lines, ...t, paid: order.method === 'tunai' ? parseRp($('cash').value) : t.total,
      };
      data.orders = [...data.orders.filter((x) => x.date === today()), o]; // simpan antrean hari ini saja
      save();
      $('toast').textContent = `Pesanan ${o.no} masuk antrean${o.method === 'tunai' ? `, kembalian ${rp(o.paid - o.total)}` : ''}.`;
      order = { type: order.type, method: order.method, lines: [] };
      $('table').value = '';
      $('cash').value = '';
      render();
    }

    document.addEventListener('click', (e) => {
      const b = e.target.closest('button');
      if (!b) return;
      const d = b.dataset;
      if (d.cat) category = d.cat;
      else if (d.add) {
        const line = order.lines.find((l) => l.name === d.add && !l.note);
        line ? line.qty++ : order.lines.push({ name: d.add, price: Number(d.price), qty: 1, note: '' });
        $('toast').textContent = '';
      } else if (d.step) {
        const l = order.lines[d.line];
        l.qty += Number(d.step);
        if (l.qty <= 0) order.lines.splice(d.line, 1);
      } else if (d.type) order.type = d.type;
      else if (d.method) order.method = d.method;
      else if (d.advance) {
        const o = data.orders.find((x) => x.no === d.advance);
        o.status = STATUS[STATUS.findIndex(([k]) => k === o.status) + 1][0];
        save();
      } else return;
      $('msg').textContent = '';
      render();
    });

    $('lines').addEventListener('input', (e) => { if (e.target.dataset.note) order.lines[e.target.dataset.note].note = e.target.value; });
    $('cash').addEventListener('input', (e) => {
      const n = parseRp(e.target.value);
      e.target.value = n ? n.toLocaleString('id-ID') : '';
      updateTotals();
    });
    $('table').addEventListener('input', updateTotals);
    $('pay').addEventListener('click', pay);
    [['set-service', 'service', 20], ['set-tax', 'tax', 10]].forEach(([id, key, max]) => {
      $(id).value = data[key];
      $(id).addEventListener('input', (e) => {
        data[key] = Math.min(max, Math.max(0, parseFloat(e.target.value) || 0));
        save();
        updateTotals();
      });
    });

    render();
  </script>
</body>
</html>
```

**Cek kebutuhan**
- **Menu per kategori** → tab Kopi, Non-kopi, dan Makanan dari objek `MENU`. Harganya hanya contoh dan bisa diganti di sana.
- **Makan di tempat dengan nomor meja, atau bawa pulang** → tombol jenis pesanan. Pesanan makan di tempat baru bisa dibayar setelah nomor meja diisi.
- **Catatan per item** → setiap baris pesanan punya kolom catatan. Menu yang sama tanpa catatan digabung jumlahnya. Menu yang sudah diberi catatan dibuat baris baru, supaya "less sugar" tidak ikut berlaku untuk gelas lain.
- **Pajak resto dan service charge** → dihitung di `totals()`.
  - Service hanya dikenakan untuk makan di tempat.
  - Pajak dihitung dari subtotal + service.
  - Persentasenya diatur di "Pengaturan pajak & service".
- **Tunai, QRIS, atau debit** → untuk tunai ada kolom uang diterima dan kembalian. Untuk QRIS dan debit, kasir menekan tombol konfirmasi setelah pembayaran berhasil di aplikasi atau mesin EDC.
- **Antrean dapur: diproses, siap, selesai**
  - Pesanan yang sudah dibayar mendapat nomor `A-001` dan seterusnya, lalu muncul di kolom Diproses bersama nomor meja dan catatannya.
  - Tombol di kartu pesanan memindahkannya ke status berikutnya.
  - Kolom Selesai hanya menampilkan 5 pesanan terakhir.

**Catatan hukum dan batasan**
- Makanan dan minuman di kafe dikenai PBJT, yaitu pajak daerah menurut UU No. 1 Tahun 2022, bukan PPN. Tarifnya paling tinggi 10% dan ditetapkan Perda, jadi isian pajak dibatasi maksimal 10%. Sesuaikan dengan tarif di daerah Anda.
- Service charge bukan pajak. UU No. 8 Tahun 1999 tentang Perlindungan Konsumen mewajibkan pelaku usaha memberikan informasi yang benar, jelas, dan jujur (Pasal 7 huruf b). Karena itu, beri tahu pelanggan soal service charge di menu atau di meja kasir sebelum mereka memesan.
- QRIS dan debit di sini hanya simulasi dan tidak memproses uang sungguhan. Pembayaran QRIS yang asli harus melalui penyelenggara jasa pembayaran yang berizin Bank Indonesia.

