  <script>
    const WORKS = [
      { year: 2026, type: 'alat', title: 'Pengingat tenggat perkara', text: 'Kalender sidang dan batas waktu upaya hukum untuk kantor hukum lima advokat, dengan pengingat harian.', tags: ['PWA', 'IndexedDB'] },
