    ];
    const $ = (id) => document.getElementById(id);

    const now = new Date();
    $('today').textContent = now.toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
    $('month').textContent = ['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'][now.getMonth()] + '/' + now.getFullYear();

    function renderWorks(filter) {
      $('works').replaceChildren(...WORKS.filter((w) => filter === 'semua' || w.type === filter).map((w) => {
        const el = document.createElement('article');
        el.className = 'work';
        el.innerHTML = '<time></time><h3></h3><p></p><div class="tags"></div>';
        el.querySelector('time').textContent = w.year;
        el.querySelector('h3').textContent = w.title;
        el.querySelector('p').textContent = w.text;
        el.querySelector('.tags').append(...w.tags.map((t) => Object.assign(document.createElement('span'), { textContent: '#' + t })));
        return el;
      }));
    }
    document.querySelector('.filters').addEventListener('click', (e) => {
      const b = e.target.closest('button');
      if (!b) return;
      document.querySelectorAll('.filters button').forEach((x) => x.setAttribute('aria-pressed', String(x === b)));
      renderWorks(b.dataset.filter);
    });
    renderWorks('semua');

    $('theme').addEventListener('click', () => {
      const root = document.documentElement;
      const dark = root.dataset.theme ? root.dataset.theme === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches;
      root.dataset.theme = dark ? 'light' : 'dark';
    });

    // Kolom tanda tangan: pointer events untuk mouse, pena, dan layar sentuh.
    const canvas = $('pad');
    const ctx = canvas.getContext('2d');
    let drawing = false, length = 0, fittedWidth = 0;
    function fit() {
      const r = canvas.getBoundingClientRect(), dpr = window.devicePixelRatio || 1;
      fittedWidth = r.width;
      canvas.width = r.width * dpr; canvas.height = r.height * dpr;
      ctx.scale(dpr, dpr);
      ctx.lineWidth = 2.2; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
      length = 0; $('agree').disabled = true;
    }
    const point = (e) => { const r = canvas.getBoundingClientRect(); return [e.clientX - r.left, e.clientY - r.top]; };
    canvas.addEventListener('pointerdown', (e) => {
      drawing = true; canvas.setPointerCapture(e.pointerId);
      ctx.strokeStyle = getComputedStyle(document.documentElement).getPropertyValue('--ink');
      ctx.beginPath(); ctx.moveTo(...point(e));
    });
    canvas.addEventListener('pointermove', (e) => {
      if (!drawing) return;
      ctx.lineTo(...point(e)); ctx.stroke();
      length++;
      $('agree').disabled = length < 15; // coretan terlalu pendek belum dianggap tanda tangan
    });
    canvas.addEventListener('pointerup', () => { drawing = false; });
    // Di HP, bilah alamat yang muncul/hilang memicu resize tanpa mengubah lebar kolom: jangan hapus tanda tangan.
    addEventListener('resize', () => { if (canvas.getBoundingClientRect().width !== fittedWidth) fit(); });
    fit();

    function reveal() {
      $('stamp').classList.remove('off');
      $('contact').hidden = false;
      $('agree').disabled = true;
    }
    $('agree').addEventListener('click', reveal);
    $('skip').addEventListener('click', () => { $('contact').hidden = false; });
    $('clear').addEventListener('click', () => { $('stamp').classList.add('off'); fit(); });
    $('copy').addEventListener('click', async () => {
      try {
        await navigator.clipboard.writeText($('mail').textContent);
        $('status').textContent = 'Surel disalin.';
      } catch (e) {
        getSelection().selectAllChildren($('mail'));
        $('status').textContent = 'Salin manual: surel sudah dipilih.';
      }
    });
  </script>
</body>
</html>
