<script>
  // Portofolio dengan filter kategori
  const works = [
    { title: 'Kopi Senja Raya', cat: 'branding', year: 2025, colors: ['#ff5c39', '#ffb199'] },
    { title: 'Bank Desa Digital', cat: 'web', year: 2025, colors: ['#7c5cff', '#2ad3ff'] },
    { title: 'Festival Pesisir', cat: 'kampanye', year: 2024, colors: ['#00c897', '#f6e05e'] },
    { title: 'Tenun Sumba Co.', cat: 'branding', year: 2024, colors: ['#b5382f', '#f2c14e'] },
    { title: 'Klinik Sehat App', cat: 'web', year: 2024, colors: ['#1fa2ff', '#a6ffcb'] },
    { title: '#JajanLokal', cat: 'kampanye', year: 2023, colors: ['#ff4ecd', '#ffd36e'] }
  ];
  const catLabel = { branding: 'Branding', web: 'Web', kampanye: 'Kampanye' };

  function renderWorks(filter) {
    const list = document.getElementById('works');
    list.innerHTML = '';
    works.filter(w => filter === 'semua' || w.cat === filter).forEach(w => {
      const card = document.createElement('article');
      card.className = 'card work';
      card.innerHTML = '<div class="art"></div><div class="meta"><div><b></b><br><small class="muted"></small></div><span class="tag"></span></div>';
      card.querySelector('.art').style.cssText = `--c1: ${w.colors[0]}; --c2: ${w.colors[1]}`;
      card.querySelector('b').textContent = w.title;
      card.querySelector('small').textContent = w.year;
      card.querySelector('.tag').textContent = catLabel[w.cat];
      list.appendChild(card);
    });
  }
  document.getElementById('filters').addEventListener('click', e => {
    const btn = e.target.closest('.chip');
    if (!btn) return;
    document.querySelectorAll('.chip').forEach(c => c.setAttribute('aria-pressed', c === btn));
    renderWorks(btn.dataset.filter);
  });
  renderWorks('semua');

  // Angka statistik naik saat terlihat di layar
  function countUp(el) {
    const target = Number(el.dataset.count);
    const start = performance.now();
    const step = now => {
      const progress = Math.min((now - start) / 1400, 1);
      el.textContent = Math.round(target * (1 - Math.pow(1 - progress, 3)));
      if (progress < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }
  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      countUp(entry.target);
      observer.unobserve(entry.target);
    });
  });
  document.querySelectorAll('[data-count]').forEach(el => observer.observe(el));

  // Testimoni bergilir (teks contoh)
  const quotes = [
    { text: '“Mereka membantu kami memahami siapa pelanggan kami sebelum mulai mendesain logo.”', role: 'Contoh: pemilik usaha kain tenun' },
    { text: '“Tim yang responsif dan jujur soal apa yang bisa dan tidak bisa dikerjakan.”', role: 'Contoh: kepala tim teknologi' },
    { text: '“Idenya sederhana, eksekusinya rapi, dan laporannya mudah dipahami.”', role: 'Contoh: manajer pemasaran' }
  ];
  const quoteEl = document.getElementById('quote');
  const dots = document.getElementById('dots');
  let quoteIndex = 0;
  let quoteTimer;

  quotes.forEach((_, i) => {
    const dot = document.createElement('button');
    dot.setAttribute('aria-label', 'Testimoni ' + (i + 1));
    dot.addEventListener('click', () => {
      showQuote(i);
      startRotation();
    });
    dots.appendChild(dot);
  });

  function showQuote(i) {
    quoteIndex = i;
    quoteEl.style.opacity = 0;
    setTimeout(() => {
      quoteEl.textContent = quotes[i].text;
      document.getElementById('quote-role').textContent = quotes[i].role;
      quoteEl.style.opacity = 1;
    }, 200);
    [...dots.children].forEach((dot, j) => dot.setAttribute('aria-current', j === i));
  }
  function startRotation() {
    clearInterval(quoteTimer);
    quoteTimer = setInterval(() => showQuote((quoteIndex + 1) % quotes.length), 6000);
  }
  showQuote(0);
  startRotation();

  // Menu HP
  const toggle = document.getElementById('menu-toggle');
  const links = document.getElementById('nav-links');
  function setMenu(open) {
    links.classList.toggle('open', open);
    toggle.setAttribute('aria-expanded', open);
    toggle.setAttribute('aria-label', open ? 'Tutup menu' : 'Buka menu');
  }
  toggle.addEventListener('click', () => setMenu(!links.classList.contains('open')));
  links.addEventListener('click', e => {
    if (e.target.tagName === 'A') setMenu(false);
  });

  // Validasi formulir kontak
  document.getElementById('contact-form').addEventListener('submit', e => {
    e.preventDefault();
    const name = document.getElementById('name').value.trim();
    const email = document.getElementById('email').value.trim();
    const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    document.getElementById('name-error').textContent = name ? '' : 'Nama wajib diisi.';
    document.getElementById('email-error').textContent = emailValid ? '' : 'Masukkan email yang valid.';
    document.getElementById('name').setAttribute('aria-invalid', !name);
    document.getElementById('email').setAttribute('aria-invalid', !emailValid);
    if (!name || !emailValid) return;
    const budget = document.getElementById('budget').value;
    document.getElementById('success').textContent = `Terima kasih, ${name}! Brief dengan anggaran ${budget} sudah kami terima.`;
    e.target.reset();
  });

  document.getElementById('year').textContent = new Date().getFullYear();
</script>
</body>
</html>
```

**Cek kebutuhan**
- **Layanan dan alur kerja** → kartu layanan dan empat langkah proses memakai gaya kartu yang sama, supaya CSS-nya tidak berulang.
- **Portofolio dengan filter** → array `works` berisi 6 karya dalam tiga kategori. `renderWorks()` membuat kartu dengan `createElement` dan `textContent`, dan tombol filter di `#filters` memakai `aria-pressed`.
- **Angka bertambah saat di-scroll** → `IntersectionObserver` memanggil `countUp()` satu kali per angka. Animasinya 1,4 detik dengan kurva ease-out lewat `requestAnimationFrame`.
- **Testimoni berganti otomatis** → `startRotation()` mengganti kutipan setiap 6 detik. Titik navigasi memakai `aria-current`, dan mengkliknya mengatur ulang timer.
- **Form kontak dengan validasi** → nama wajib diisi, dan email dicek dengan regex. Pesan galat terhubung lewat `aria-describedby` dan `aria-invalid`. Pesan sukses di `#success` (`role="status"`) menyebut nama dan anggaran, lalu form dikosongkan.
- **Menu di HP** → di bawah 820px, `#menu-toggle` membuka menu dengan `aria-expanded`, dan menu tertutup lagi saat salah satu tautan diklik.

Testimoni diberi label "Contoh testimoni (teks ilustrasi, bukan ulasan klien sungguhan)". Ganti dengan ulasan asli beserta izin kliennya sebelum website dipakai, karena testimoni karangan yang tampil seperti ulasan asli bisa menyesatkan konsumen (Pasal 9 dan 10 UU No. 8 Tahun 1999 tentang Perlindungan Konsumen). Nama karya di portofolio juga sengaja dibuat fiktif supaya tidak memakai merek milik orang lain.

