      </section>
    </div>

    <section class="card">
      <h2>24 jam ke depan</h2>
      <div class="chart-wrap">
        <svg class="chart" id="chart" viewBox="0 0 720 190" preserveAspectRatio="none" role="img" aria-label="Grafik suhu dan peluang hujan 24 jam"></svg>
      </div>
    </section>

    <section class="card">
      <h2>7 hari</h2>
      <div id="daily"></div>
    </section>
  </main>

  <footer class="muted">Data contoh (simulasi) untuk demo, bukan prakiraan resmi.</footer>
</div>

<script>
  // Data simulasi: dibangkitkan dari "iklim" tiap kota supaya halaman jalan tanpa internet.
  const cities = [
    { name: 'Jakarta', prov: 'DKI Jakarta', base: 31, wet: .55, tz: 7 },
    { name: 'Bandung', prov: 'Jawa Barat', base: 26, wet: .6, tz: 7 },
    { name: 'Surabaya', prov: 'Jawa Timur', base: 32, wet: .45, tz: 7 },
    { name: 'Medan', prov: 'Sumatera Utara', base: 30, wet: .6, tz: 7 },
    { name: 'Yogyakarta', prov: 'DI Yogyakarta', base: 29, wet: .5, tz: 7 },
    { name: 'Denpasar', prov: 'Bali', base: 30, wet: .4, tz: 8 },
    { name: 'Makassar', prov: 'Sulawesi Selatan', base: 31, wet: .5, tz: 8 },
    { name: 'Jayapura', prov: 'Papua', base: 30, wet: .6, tz: 9 }
  ];
  const tzName = { 7: 'WIB', 8: 'WITA', 9: 'WIT' };
  const icons = { cerah: '☀️', malam: '🌙', berawan: '⛅', hujan: '🌧️' };
  let unit = 'C';
  let current = cities[0];

  // Acak dengan seed supaya data tiap kota tetap sama sepanjang hari
  function rng(seed) {
    return () => {
      seed = (seed * 16807) % 2147483647;
      return (seed - 1) / 2147483646;
    };
  }
  function seedOf(text) {
    let h = 7;
    for (const ch of text) h = (h * 31 + ch.charCodeAt(0)) % 2147483647;
    return h + new Date().getDate();
  }

  function forecast(city) {
    const r = rng(seedOf(city.name));
    const now = new Date(Date.now() + (city.tz - 7) * 3600e3);
    const hourNow = now.getHours();
    const hours = [];
    for (let i = 0; i < 24; i++) {
      const h = (hourNow + i) % 24;
      const temp = city.base - 4 + Math.sin((h - 9) / 24 * Math.PI * 2) * 4 + r() * 1.5;
      const afternoon = h >= 13 && h <= 18 ? 25 : -10;
      const rain = Math.round(Math.min(95, Math.max(0, city.wet * 70 + afternoon + r() * 20 - 10)));
      hours.push({ h, temp, rain });
    }
    const days = [];
    for (let d = 0; d < 7; d++) {
      const hi = city.base + r() * 3 - 1;
      const lo = hi - 6 - r() * 3;
      const rain = Math.round(Math.min(95, city.wet * 80 + r() * 30 - 15));
      days.push({ date: new Date(now.getTime() + d * 864e5), hi, lo, rain });
    }
    return {
      now, hours, days,
      hum: Math.round(55 + city.wet * 40 + r() * 5),
      wind: Math.round(5 + r() * 18),
      uv: hourNow >= 6 && hourNow <= 17 ? Math.round(4 + r() * 7) : 0
    };
  }

  function condition(rain, hour) {
    const night = hour < 6 || hour >= 18;
    if (rain >= 65) return { key: 'hujan', text: rain >= 80 ? 'Hujan petir' : 'Hujan ringan' };
    if (rain >= 40) return { key: 'berawan', text: 'Berawan' };
    return { key: night ? 'malam' : 'cerah', text: night ? 'Cerah malam' : 'Cerah' };
  }

  const toUnit = c => unit === 'C' ? c : c * 9 / 5 + 32;
  const fmt = c => Math.round(toUnit(c)) + '°';
  const pad2 = n => String(n).padStart(2, '0');
  const setText = (id, text) => { document.getElementById(id).textContent = text; };

  function render() {
    const f = forecast(current);
    const nowHour = f.hours[0];
    const cond = condition(nowHour.rain, nowHour.h);
    document.body.className = cond.key;
    setText('city-name', current.name);
    setText('date', f.now.toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long' }) +
      ` · ${pad2(f.now.getHours())}:${pad2(f.now.getMinutes())} ${tzName[current.tz]}`);
    setText('temp', fmt(nowHour.temp));
    setText('cond', cond.text);
    setText('feels', 'Terasa seperti ' + fmt(nowHour.temp + (f.hum - 60) / 10));
    setText('big-icon', icons[cond.key]);
    setText('hum', f.hum + '%');
    setText('wind', f.wind + ' km/j');
    setText('uv', f.uv + (f.uv >= 8 ? ' Sangat tinggi' : f.uv >= 6 ? ' Tinggi' : f.uv >= 3 ? ' Sedang' : ' Rendah'));
    setText('rain', nowHour.rain + '%');
    setText('advice', nowHour.rain >= 60 ? '☂️ Bawa payung atau jas hujan sebelum berangkat.'
      : f.uv >= 6 ? '🧴 Matahari terik. Pakai tabir surya dan banyak minum air.'
      : '😎 Cuaca bersahabat untuk beraktivitas di luar.');
    drawChart(f.hours);
    renderDaily(f.days);
  }

  // Grafik SVG: kurva suhu + batang peluang hujan tiap 3 jam
  function drawChart(hours) {
    const W = 720, pad = 30;
    const temps = hours.map(h => toUnit(h.temp));
    const min = Math.min(...temps) - 2, max = Math.max(...temps) + 2;
    const x = i => pad + i * (W - pad * 2) / (hours.length - 1);
    const y = t => 30 + (1 - (t - min) / (max - min)) * 95;
    let d = `M${x(0)} ${y(temps[0])}`;
    for (let i = 1; i < temps.length; i++) {
      const cx = (x(i - 1) + x(i)) / 2;
      d += ` C${cx} ${y(temps[i - 1])} ${cx} ${y(temps[i])} ${x(i)} ${y(temps[i])}`;
    }
    let svg = `<path d="${d} L${x(23)} 135 L${x(0)} 135Z" fill="rgba(255,255,255,.18)"/>` +
      `<path d="${d}" fill="none" stroke="#fff" stroke-width="2.5"/>`;
    hours.forEach((h, i) => {
      if (i % 3) return;
      const label = i === 0 ? 'Kini' : pad2(h.h) + ':00';
      svg += `<circle cx="${x(i)}" cy="${y(temps[i])}" r="4" fill="#fff"/>
        <text x="${x(i)}" y="${y(temps[i]) - 10}" fill="#fff" font-size="13" text-anchor="middle">${Math.round(temps[i])}°</text>
        <rect x="${x(i) - 9}" y="${170 - h.rain * .3}" width="18" height="${h.rain * .3}" rx="3" fill="#9fd8ff"/>
        <text x="${x(i)}" y="186" fill="#fff" font-size="12" text-anchor="middle">${label}</text>`;
    });
    document.getElementById('chart').innerHTML = svg;
  }

  function renderDaily(days) {
    const lo = Math.min(...days.map(d => d.lo));
    const hi = Math.max(...days.map(d => d.hi));
    document.getElementById('daily').innerHTML = days.map((d, i) => {
      const left = (d.lo - lo) / (hi - lo) * 100;
      const width = (d.hi - d.lo) / (hi - lo) * 100;
      const name = i === 0 ? 'Hari ini' : d.date.toLocaleDateString('id-ID', { weekday: 'short', day: 'numeric' });
      return `<div class="day"><span>${name}</span><span aria-hidden="true">${icons[condition(d.rain, 12).key]}</span>
        <div class="range"><span class="muted">${fmt(d.lo)}</span><div class="bar"><i style="left:${left}%;width:${width}%"></i></div><span>${fmt(d.hi)}</span></div></div>`;
    }).join('');
  }

  // Pencarian kota: ketik, lalu ↑/↓ untuk memilih, Enter untuk membuka, Esc untuk menutup
  const input = document.getElementById('city-input');
  const suggest = document.getElementById('suggest');
  let matches = [];
  let highlighted = 0;

  function setOpen(open) {
    suggest.hidden = !open;
    input.setAttribute('aria-expanded', open);
  }
  function highlight(i) {
    highlighted = i;
    [...suggest.children].forEach((li, j) => {
      li.classList.toggle('hl', j === i);
      li.setAttribute('aria-selected', j === i);
    });
    if (matches.length) input.setAttribute('aria-activedescendant', 'opt-' + i);
    else input.removeAttribute('aria-activedescendant');
  }
  function showSuggest() {
    const q = input.value.trim().toLowerCase();
    matches = q ? cities.filter(c => (c.name + ' ' + c.prov).toLowerCase().includes(q)) : [];
    suggest.innerHTML = matches.length
      ? matches.map((c, i) => `<li id="opt-${i}" role="option" data-i="${i}">${c.name}<small>${c.prov}</small></li>`).join('')
      : '<li role="option" aria-disabled="true">Kota tidak ditemukan</li>';
    highlight(0);
    setOpen(q !== '');
  }
  function pick(city) {
    current = city;
    input.value = '';
    setOpen(false);
    render();
  }

  input.addEventListener('input', showSuggest);
  input.addEventListener('keydown', e => {
    if ((e.key === 'ArrowDown' || e.key === 'ArrowUp') && matches.length) {
      e.preventDefault();
      const step = e.key === 'ArrowDown' ? 1 : -1;
      highlight((highlighted + step + matches.length) % matches.length);
    } else if (e.key === 'Enter' && matches[highlighted]) {
      pick(matches[highlighted]);
    } else if (e.key === 'Escape') {
      setOpen(false);
    }
  });
  suggest.addEventListener('click', e => {
    const li = e.target.closest('li[data-i]');
    if (li) pick(matches[li.dataset.i]);
  });
  document.addEventListener('click', e => {
    if (!e.target.closest('.search')) setOpen(false);
  });

  // Satuan suhu, disimpan di localStorage
  function setUnit(u) {
    unit = u;
    document.getElementById('unit-c').setAttribute('aria-pressed', u === 'C');
    document.getElementById('unit-f').setAttribute('aria-pressed', u === 'F');
    try { localStorage.setItem('langit-unit', u); } catch (e) {}
    render();
  }
  document.getElementById('unit-c').addEventListener('click', () => setUnit('C'));
  document.getElementById('unit-f').addEventListener('click', () => setUnit('F'));
  try {
    if (localStorage.getItem('langit-unit') === 'F') unit = 'F';
  } catch (e) {}
  setUnit(unit);
</script>
</body>
</html>
```

**Cek kebutuhan**
- **Data simulasi tanpa API** → `rng()` adalah generator acak dengan seed, dan `seedOf()` menggabungkan nama kota dengan tanggal. Hasilnya, data tetap sama sepanjang hari dan tidak berubah setiap halaman dimuat ulang. `forecast()` membuat suhu 24 jam berbentuk gelombang sinus, dengan peluang hujan lebih tinggi pukul 13.00–18.00.
- **Pencarian kota dengan keyboard** → combobox dengan `role="combobox"`, `aria-expanded`, dan `aria-activedescendant`. ↑/↓ memindah sorotan, Enter memilih, dan Esc menutup daftar. Pencarian mencocokkan nama kota dan provinsi.
- **Kondisi saat ini** → `render()` mengisi suhu, "terasa seperti", kelembapan, angin, peluang hujan, dan UV (Rendah, Sedang ≥3, Tinggi ≥6, Sangat tinggi ≥8). Ada juga saran membawa payung atau memakai tabir surya. `condition()` juga menentukan warna latar halaman.
- **Grafik suhu 24 jam** → `drawChart()` menggambar SVG berisi kurva halus dan batang hujan setiap 3 jam. Grafik berada di wadah `overflow-x: auto`, jadi halamannya sendiri tidak bergeser ke samping di HP.
- **Prakiraan 7 hari** → `renderDaily()` menampilkan ikon dan bilah suhu terendah–tertinggi yang posisinya dibandingkan dengan rentang suhu seminggu.
- **°C/°F yang tersimpan** → `setUnit()` mengonversi dengan c × 9/5 + 32 dan menyimpan pilihan di `localStorage` di dalam `try/catch`.
- **Zona waktu yang benar** → setiap kota punya `tz` 7, 8, atau 9, sehingga jam lokal dan label WIB, WITA, atau WIT sesuai dengan kotanya, misalnya Denpasar WITA dan Jayapura WIT.

Untuk memakai data asli, ganti `forecast()` dengan pemanggilan API cuaca. Bagian tampilannya tidak perlu diubah.

