      <button class="ctl" id="prev" aria-label="Sebelumnya"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 5h2v14H6zM20 5v14L9 12z"/></svg></button>
      <button class="ctl play" id="play" aria-label="Putar"><svg viewBox="0 0 24 24" aria-hidden="true"><path id="play-icon" d="M7 4v16l13-8z"/></svg></button>
