    <label class="volume muted">🔈<input type="range" id="volume" min="0" max="1" step="0.01" value="0.7" aria-label="Volume">🔊</label>
    <p class="hint muted"><kbd>Spasi</kbd> putar/jeda · <kbd>←</kbd> <kbd>→</kbd> geser 5 detik · <kbd>N</kbd> lagu berikutnya</p>
  </section>

  <section class="panel" aria-labelledby="list-title">
    <h2 id="list-title">Daftar Putar</h2>
    <div id="tracks"></div>
  </section>
</main>

<script>
  // Lagu dibangkitkan dengan Web Audio dari tangga nada lima nada, jadi tidak ada file audio yang diunduh.
  const SCALES = {
    slendro: [0, 2, 5, 7, 9],
    pelog: [0, 1, 3, 7, 8],
    mayor: [0, 2, 4, 7, 9],
    minor: [0, 3, 5, 7, 10]
  };
  const tracks = [
    { title: 'Fajar di Dieng', artist: 'Orkes Sintetis', scale: 'slendro', root: 62, bpm: 92, seed: 11, wave: 'triangle', colors: ['#f7b733', '#fc4a1a'] },
    { title: 'Ombak Parangtritis', artist: 'Gamelan Digital', scale: 'pelog', root: 60, bpm: 76, seed: 23, wave: 'sine', colors: ['#00c6ff', '#0072ff'] },
    { title: 'Pasar Malam', artist: 'Chiptune Nusantara', scale: 'mayor', root: 67, bpm: 128, seed: 5, wave: 'square', colors: ['#ff4ecd', '#7c5cff'] },
    { title: 'Gerimis Sore', artist: 'Orkes Sintetis', scale: 'minor', root: 57, bpm: 70, seed: 42, wave: 'sine', colors: ['#5f7ea3', '#283e51'] },
    { title: 'Lari Pagi Senayan', artist: 'Chiptune Nusantara', scale: 'slendro', root: 64, bpm: 140, seed: 77, wave: 'sawtooth', colors: ['#00c897', '#f6e05e'] }
  ];
  const BARS = 16, STEPS_PER_BAR = 8;
  tracks.forEach(t => {
    t.duration = BARS * STEPS_PER_BAR * (60 / t.bpm / 2);
    t.notes = compose(t);
  });

  // Susun melodi dari motif acak (seed tetap), progresi bas, hi-hat, dan kick
  function compose(t) {
    let s = t.seed;
    const r = () => { s = (s * 16807) % 2147483647; return (s - 1) / 2147483646; };
    const scale = SCALES[t.scale];
    const motif = Array.from({ length: STEPS_PER_BAR * 2 }, () => r() < .7 ? Math.floor(r() * 8) : null);
    const progression = [0, 3, 4, 2].map(i => scale[i]);
    const notes = [];
    for (let bar = 0; bar < BARS; bar++) {
      for (let st = 0; st < STEPS_PER_BAR; st++) {
        const step = bar * STEPS_PER_BAR + st;
        const m = motif[(bar % 2) * STEPS_PER_BAR + st];
        if (m !== null) {
          const deg = m + (bar >= 8 ? 2 : 0);
          const midi = t.root + scale[deg % 5] + 12 * Math.floor(deg / 5) + (bar % 4 === 3 ? -2 : 0);
          notes.push({ step, midi, len: r() < .3 ? 2 : 1, kind: 'lead' });
        }
        if (st % 4 === 0) notes.push({ step, midi: t.root - 24 + progression[bar % 4], len: 3, kind: 'bass' });
        if (st % 2 === 1) notes.push({ step, kind: 'hat' });
        if (st === 0 || (st === 4 && t.bpm > 100)) notes.push({ step, kind: 'kick' });
      }
    }
    return notes;
  }

  let ctx, master, analyser, noiseBuf;
  let idx = 0, playing = false, startedAt = 0, offset = 0, nextNote = 0, timer = null;
  let shuffle = false, repeat = false;
  const live = new Set();

  function ensureAudio() {
    if (ctx) return;
    ctx = new AudioContext();
    master = ctx.createGain();
    master.gain.value = Number(document.getElementById('volume').value);
    analyser = ctx.createAnalyser();
    analyser.fftSize = 256;
    master.connect(analyser);
    analyser.connect(ctx.destination);
    noiseBuf = ctx.createBuffer(1, ctx.sampleRate * .2, ctx.sampleRate);
    const data = noiseBuf.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  }

  const stepDur = () => 60 / tracks[idx].bpm / 2;
  const freq = midi => 440 * Math.pow(2, (midi - 69) / 12);

  function playNote(n, when) {
    const t = tracks[idx];
    const dur = stepDur() * (n.len || 1);
    const gain = ctx.createGain();
    gain.connect(master);
    let src;
    if (n.kind === 'hat') {
      src = ctx.createBufferSource();
      src.buffer = noiseBuf;
      const highpass = new BiquadFilterNode(ctx, { type: 'highpass', frequency: 7000 });
      src.connect(highpass).connect(gain);
      gain.gain.setValueAtTime(.08, when);
      gain.gain.exponentialRampToValueAtTime(.001, when + .05);
    } else if (n.kind === 'kick') {
      src = ctx.createOscillator();
      src.connect(gain);
      src.frequency.setValueAtTime(150, when);
      src.frequency.exponentialRampToValueAtTime(40, when + .15);
      gain.gain.setValueAtTime(.6, when);
      gain.gain.exponentialRampToValueAtTime(.001, when + .2);
    } else {
      src = ctx.createOscillator();
      src.connect(gain);
      src.type = n.kind === 'bass' ? 'triangle' : t.wave;
      src.frequency.value = freq(n.midi);
      const harsh = t.wave === 'square' || t.wave === 'sawtooth';
      const peak = n.kind === 'bass' ? .25 : harsh ? .07 : .18;
      gain.gain.setValueAtTime(0, when);
      gain.gain.linearRampToValueAtTime(peak, when + .01);
      gain.gain.exponentialRampToValueAtTime(.001, when + dur * .95);
    }
    src.start(when);
    src.stop(when + Math.max(dur, .25));
    live.add(src);
    src.onended = () => live.delete(src);
  }

  // Penjadwal: tiap 25 ms, antrekan not yang jatuh dalam 150 ms ke depan
  function schedule() {
    const t = tracks[idx], sd = stepDur();
    while (nextNote < t.notes.length) {
      const n = t.notes[nextNote];
      const when = startedAt + n.step * sd;
      if (when > ctx.currentTime + .15) break;
      if (when >= ctx.currentTime - .01) playNote(n, Math.max(when, ctx.currentTime));
      nextNote++;
    }
    if (position() >= t.duration) ended();
  }

  function position() {
    return playing ? ctx.currentTime - startedAt : offset;
  }

  function start(from) {
    ensureAudio();
    if (ctx.state === 'suspended') ctx.resume();
    stopSources();
    offset = from;
    startedAt = ctx.currentTime - from;
    const sd = stepDur();
    nextNote = tracks[idx].notes.findIndex(n => n.step * sd >= from - .001);
    if (nextNote < 0) nextNote = tracks[idx].notes.length;
    playing = true;
    clearInterval(timer);
    timer = setInterval(schedule, 25);
    schedule();
    updateState();
  }
  function pause() {
    if (!playing) return;
    offset = position();
    playing = false;
    clearInterval(timer);
    stopSources();
    updateState();
  }
  function stopSources() {
    live.forEach(src => { try { src.stop(); } catch (e) {} });
    live.clear();
  }
  function ended() {
    if (repeat) start(0);
    else next(true);
  }
  function seekTo(seconds) {
    if (playing) start(seconds);
    else offset = seconds;
  }

  function load(i, autoplay) {
    pause();
    idx = (i + tracks.length) % tracks.length;
    offset = 0;
    const t = tracks[idx];
    document.getElementById('t-title').textContent = t.title;
    document.getElementById('t-meta').textContent = `${t.artist} · ${t.scale} · ${t.bpm} BPM`;
    document.getElementById('total').textContent = mmss(t.duration);
    document.getElementById('disc').style.background = `conic-gradient(${t.colors[0]}, ${t.colors[1]}, ${t.colors[0]})`;
    document.title = t.title + ' — Gending';
    renderList();
    if (autoplay) start(0);
    else updateState();
  }
  function next(auto) {
    if (shuffle) {
      let j;
      do { j = Math.floor(Math.random() * tracks.length); } while (j === idx);
      return load(j, true);
    }
    // Setelah lagu terakhir habis (tanpa ulangi), kembali ke awal dan berhenti
    if (auto && idx === tracks.length - 1) return load(0, false);
    load(idx + 1, true);
  }
  function prev() {
    if (position() > 3) start(0);
    else load(idx - 1, true);
  }

  const mmss = s => Math.floor(s / 60) + ':' + String(Math.floor(s % 60)).padStart(2, '0');

  function updateState() {
    document.getElementById('app').classList.toggle('playing', playing);
    document.getElementById('play').setAttribute('aria-label', playing ? 'Jeda' : 'Putar');
    document.getElementById('play-icon').setAttribute('d', playing ? 'M6 4h4v16H6zm8 0h4v16h-4z' : 'M7 4v16l13-8z');
  }

  function renderList() {
    document.getElementById('tracks').innerHTML = tracks.map((t, i) => `
      <button class="track" data-i="${i}" aria-current="${i === idx}">
        <span class="thumb" style="background: linear-gradient(135deg, ${t.colors[0]}, ${t.colors[1]})" aria-hidden="true">${i === idx ? '♪' : ''}</span>
        <span>${t.title}<small>${t.artist}</small></span>
        <span class="muted">${mmss(t.duration)}</span>
      </button>`).join('');
  }
  document.getElementById('tracks').addEventListener('click', e => {
    const btn = e.target.closest('.track');
    if (!btn) return;
    const i = Number(btn.dataset.i);
    if (i !== idx) load(i, true);
    else if (playing) pause();
    else start(offset);
  });

  document.getElementById('play').addEventListener('click', () => {
    if (playing) pause();
    else start(offset >= tracks[idx].duration ? 0 : offset);
  });
  document.getElementById('next').addEventListener('click', () => next(false));
  document.getElementById('prev').addEventListener('click', prev);
  document.getElementById('shuffle').addEventListener('click', e => {
    shuffle = !shuffle;
    e.currentTarget.setAttribute('aria-pressed', shuffle);
  });
  document.getElementById('repeat').addEventListener('click', e => {
    repeat = !repeat;
    e.currentTarget.setAttribute('aria-pressed', repeat);
  });

  const seek = document.getElementById('seek');
  let seeking = false;
  seek.addEventListener('input', () => {
    seeking = true;
    document.getElementById('cur').textContent = mmss(seek.value / 100 * tracks[idx].duration);
  });
  seek.addEventListener('change', () => {
    seeking = false;
    seekTo(seek.value / 100 * tracks[idx].duration);
  });
  document.getElementById('volume').addEventListener('input', e => {
    if (master) master.gain.value = Number(e.target.value);
  });

  // Pintasan keyboard (slider tetap memakai panahnya sendiri)
  document.addEventListener('keydown', e => {
    if (e.target.type === 'range' && e.code !== 'Space') return;
    if (e.code === 'Space') {
      e.preventDefault();
      document.getElementById('play').click();
    } else if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
      const delta = e.key === 'ArrowRight' ? 5 : -5;
      seekTo(Math.min(Math.max(position() + delta, 0), tracks[idx].duration - .1));
    } else if (e.key.toLowerCase() === 'n') {
      next(false);
    }
  });

  // Visualizer melingkar: 64 garis dari data frekuensi analyser
  const canvas = document.getElementById('viz');
  const g2 = canvas.getContext('2d');
  const bins = new Uint8Array(128);
  function draw(ts) {
    g2.clearRect(0, 0, 600, 600);
    if (analyser && playing) analyser.getByteFrequencyData(bins);
    else for (let i = 0; i < bins.length; i++) bins[i] = 30 + 20 * Math.sin(ts / 600 + i / 6);
    g2.lineWidth = 6;
    g2.lineCap = 'round';
    for (let i = 0; i < 64; i++) {
      const v = bins[Math.floor(i * 1.5)] / 255;
      const angle = i / 64 * Math.PI * 2 - Math.PI / 2;
      const r1 = 138, r2 = 142 + v * 130;
      g2.strokeStyle = `rgba(255, 255, 255, ${.35 + v * .6})`;
      g2.beginPath();
      g2.moveTo(300 + Math.cos(angle) * r1, 300 + Math.sin(angle) * r1);
      g2.lineTo(300 + Math.cos(angle) * r2, 300 + Math.sin(angle) * r2);
      g2.stroke();
    }
    if (!seeking) {
      const p = Math.min(position(), tracks[idx].duration);
      seek.value = p / tracks[idx].duration * 100;
      document.getElementById('cur').textContent = mmss(p);
    }
    requestAnimationFrame(draw);
  }

  load(0, false);
  requestAnimationFrame(draw);
</script>
</body>
</html>
```

**Cek kebutuhan**
- **Lagu buatan sendiri dengan Web Audio** → `compose()` menyusun 16 birama dari motif acak bertitik awal (seed) tetap, progresi bas, hi-hat, dan kick. `playNote()` membunyikan melodi dan bas dengan oscillator dan envelope, hi-hat dari derau dengan filter highpass, dan kick dari frekuensi yang turun 150→40 Hz.
- **Nuansa gamelan** → `SCALES` berisi slendro dan pelog selain mayor dan minor, dan dua lagu pertama memakai tangga nada itu.
- **Playlist** → `renderList()` membuat tombol per lagu dengan `aria-current` untuk lagu aktif. Mengklik lagu lain memutarnya, sedangkan mengklik lagu yang sedang aktif menjeda atau melanjutkan.
- **Play/pause, next/prev** → `start()` dan `pause()` menyimpan posisi lagu. `prev()` kembali ke awal lagu jika lagu sudah berjalan lebih dari 3 detik.
- **Shuffle dan repeat** → tombol dengan `aria-pressed`. Shuffle tidak pernah memilih lagu yang sama dua kali berturut-turut.
- **Geser posisi dan volume** → `#seek` memperbarui label waktu selama digeser dan baru melompat saat dilepas (`seekTo()`). `#volume` mengatur gain utama.
- **Visualizer** → `draw()` menggambar 64 garis melingkar dari `AnalyserNode.getByteFrequencyData` di kanvas, dengan animasi diam saat jeda.
- **Shortcut keyboard** → Spasi untuk putar/jeda, ←/→ untuk mundur/maju 5 detik, N untuk lagu berikutnya. Tombol panah tidak diambil alih saat fokus ada di slider.

Nada dijadwalkan dengan pola *lookahead*: `schedule()` berjalan setiap 25 ms dan memasukkan nada yang jatuh dalam 150 ms ke depan berdasarkan jam `AudioContext`, jadi tempo tetap stabil walaupun timer JavaScript terlambat. `AudioContext` baru dibuat saat tombol putar pertama kali ditekan, sesuai aturan autoplay browser.

