    if (n >= 10) return String(Math.round(n));
    const whole = Math.floor(n), frac = n - whole;
    const fractions = [[0, ''], [.25, '¼'], [.33, '⅓'], [.5, '½'], [.67, '⅔'], [.75, '¾'], [1, '']];
    const [value, sign] = fractions.reduce((a, b) => Math.abs(b[0] - frac) < Math.abs(a[0] - frac) ? b : a);
    const w = whole + (value === 1 ? 1 : 0);
    return (w || '') + sign || '0';
  }

  function openRecipe(id) {
    current = recipes.find(r => r.id === id);
    portions = current.serves;
    $('m-title').textContent = `${current.emoji} ${current.name}`;
    $('m-meta').textContent = `⏱ ${fmtTime(current.time)} · ${current.level} · ${current.region}`;
    $('m-steps').innerHTML = current.steps.map(s => {
      const m = s.match(/ \[(\d+)\]$/);
      const text = m ? s.slice(0, m.index) : s;
      return `<li>${text}${m ? ` <button class="pill timer-btn" data-min="${m[1]}">⏲ ${m[1]} mnt</button>` : ''}</li>`;
    }).join('');
    renderIng();
    $('modal').showModal();
    moveTimerBar($('modal'));
  }
  function renderIng() {
    $('portions').textContent = portions + ' porsi';
    const k = portions / current.serves;
    $('m-ing').innerHTML = current.ing.map(([qty, unit, name]) =>
      `<li><label><input type="checkbox"><span><b>${fmtQty(qty * k)} ${unit}</b> ${name}</span></label></li>`).join('');
  }
  $('minus').addEventListener('click', () => { if (portions > 1) { portions--; renderIng(); } });
  $('plus').addEventListener('click', () => { if (portions < 20) { portions++; renderIng(); } });
  $('close').addEventListener('click', () => $('modal').close());
  $('modal').addEventListener('close', () => moveTimerBar(document.body));
  $('m-steps').addEventListener('click', e => {
    const btn = e.target.closest('.timer-btn');
    if (btn) startTimer(+btn.dataset.min, current.name);
    else e.target.closest('li')?.classList.toggle('done');
  });

  // Isi luar dialog modal tidak bisa diklik, jadi bar timer ikut pindah ke dalam dialog
  function moveTimerBar(parent) {
    const bar = $('timer-bar'), shown = bar.matches(':popover-open');
    parent.append(bar);
    if (shown) bar.showPopover();
  }

  function startTimer(min, label) {
    clearInterval(timerId);
    const end = Date.now() + min * 60000;
    $('timer-label').textContent = label;
    $('timer-bar').hidePopover();
    $('timer-bar').showPopover();
    const tick = () => {
      const left = Math.max(0, end - Date.now());
      $('timer-left').textContent = `${Math.floor(left / 60000)}:${String(Math.floor(left / 1000) % 60).padStart(2, '0')}`;
      if (!left) {
        clearInterval(timerId);
        $('timer-left').textContent = 'Waktunya cek masakan!';
      }
    };
    tick();
    timerId = setInterval(tick, 500);
  }
  $('timer-stop').addEventListener('click', () => {
    clearInterval(timerId);
    $('timer-bar').hidePopover();
  });

  render();
</script>
</body>
</html>
```

**Cek kebutuhan**
- **Cari berdasarkan nama atau bahan** → `render()` mencocokkan nama resep, daerah, dan setiap nama bahan. Misalnya "santan" menemukan Rendang dan Es Cendol. `#count` menampilkan jumlah hasil.
- **Resep favorit** → tombol hati (`aria-pressed`) menyimpan `Set` favorit ke `localStorage` di dalam `try/catch`. `#fav-toggle` menyaring daftar hanya ke favorit.
- **Detail resep** → `openRecipe()` membuka `<dialog>` dengan `showModal()`, jadi fokus terkunci di dalamnya dan Esc menutupnya. Seluruh kartu bisa diklik lewat tombol judul yang `::after`-nya menutupi kartu, sehingga tidak ada tombol bersarang di dalam tombol.
- **Takaran mengikuti porsi** → tombol − dan + mengatur 1–20 porsi. `renderIng()` mengalikan jumlah dengan `porsi ÷ serves`, dan `fmtQty()` membulatkan ke pecahan dapur (¼, ⅓, ½, ⅔, ¾).
- **Centang bahan dan langkah** → bahan yang dicentang dicoret, dan langkah yang diklik ditandai selesai.
- **Timer memasak** → langkah yang diakhiri `[n]` di data mendapat tombol timer n menit. `startTimer()` menghitung sisa waktu dari `Date.now()`, jadi tetap akurat walaupun tab sempat tidak aktif.

Bilah timer adalah elemen `popover`. `moveTimerBar()` memindahkannya ke dalam dialog saat dialog terbuka, karena elemen di luar dialog modal tidak bisa diklik. Dengan begitu, tombol Batal tetap bisa dipakai.

Berikut perencana liburan **Jelajah Nusantara** dalam satu file HTML. Semua harga adalah estimasi contoh, dan halaman menyebutkan hal itu.

