</style>
</head>
<body>
<header class="hero">
  <div class="wrap">
    <nav aria-label="Navigasi utama"><b>🧭 Jelajah Nusantara</b><a href="#rencana">Rencana Saya</a></nav>
    <h1>17.000 pulau.<br>Satu liburan impian.</h1>
    <p>Pilih destinasi, atur lama menginap, dan lihat perkiraan biayanya langsung.</p>
  </div>
</header>

<main class="wrap">
  <form class="finder" id="finder" role="search">
    <label>Cari destinasi<input id="q" type="search" placeholder="Pantai, gunung, budaya…"></label>
    <label>Pulau<select id="island"><option value="">Semua pulau</option></select></label>
    <label>Anggaran per malam
      <select id="budget">
        <option value="">Semua</option>
        <option value="500000">≤ Rp500 ribu</option>
        <option value="1000000">≤ Rp1 juta</option>
        <option value="2000000">≤ Rp2 juta</option>
      </select>
    </label>
  </form>

  <div class="layout">
    <section aria-labelledby="judul-destinasi">
      <div class="section-title">
        <h2 id="judul-destinasi">Destinasi pilihan</h2>
        <span id="result-count" aria-live="polite"></span>
      </div>
      <div class="dests" id="dests"></div>
    </section>

    <aside class="planner" id="rencana" aria-labelledby="judul-rencana">
      <h2 id="judul-rencana">Rencana Perjalanan</h2>
      <ul class="trip" id="trip"></ul>
      <p class="empty" id="trip-empty">🗺️<br>Belum ada destinasi.<br>Klik “+ Rencana” untuk memulai.</p>
      <label class="people">Jumlah orang <input id="people" type="number" min="1" max="10" value="2"></label>
      <div class="breakdown" aria-live="polite">
        <div><span id="stay-label">Penginapan</span><span id="stay"></span></div>
        <div><span id="fare-label">Tiket pesawat</span><span id="fare"></span></div>
        <div><span>Makan &amp; transport lokal</span><span id="daily"></span></div>
        <div class="total"><span>Total</span><span id="total"></span></div>
        <div class="meta"><span>Per orang</span><span id="per-person"></span></div>
      </div>
      <ol class="itinerary" id="itinerary" aria-label="Garis besar jadwal"></ol>
      <button class="share" id="share" type="button">Salin Ringkasan</button>
      <p class="note" id="share-status" role="status"></p>
      <p class="note">Semua harga adalah perkiraan: penginapan per kamar (2 orang) per malam, tiket pesawat pulang-pergi dari Jakarta, serta Rp300.000 per orang per hari untuk makan dan transport lokal.</p>
    </aside>
  </div>
</main>

<script>
  // Harga contoh (perkiraan): stay = penginapan per kamar per malam, fare = tiket PP dari Jakarta per orang.
  const dests = [
    { id: 'raja-ampat', name: 'Raja Ampat', island: 'Papua', type: 'Laut', rating: 4.9, stay: 1800000, fare: 7200000, desc: 'Gugusan pulau karst dengan terumbu karang terkaya di dunia.' },
    { id: 'bromo', name: 'Gunung Bromo', island: 'Jawa', type: 'Gunung', rating: 4.8, stay: 550000, fare: 1600000, desc: 'Matahari terbit di atas lautan pasir dan kawah yang masih aktif.' },
    { id: 'labuan-bajo', name: 'Labuan Bajo', island: 'Nusa Tenggara', type: 'Laut', rating: 4.8, stay: 1200000, fare: 3400000, desc: 'Gerbang menuju Pulau Komodo, Padar, dan Pink Beach.' },
    { id: 'toba', name: 'Danau Toba', island: 'Sumatera', type: 'Danau', rating: 4.7, stay: 450000, fare: 2400000, desc: 'Danau vulkanik terbesar di Asia Tenggara dengan Pulau Samosir di tengahnya.' },
    { id: 'ubud', name: 'Ubud', island: 'Bali', type: 'Budaya', rating: 4.7, stay: 900000, fare: 1900000, desc: 'Sawah terasering, pura, dan pusat seni tradisional Bali.' },
    { id: 'borobudur', name: 'Borobudur', island: 'Jawa', type: 'Budaya', rating: 4.8, stay: 600000, fare: 1300000, desc: 'Candi Buddha terbesar di dunia, warisan budaya UNESCO.' },
    { id: 'derawan', name: 'Kepulauan Derawan', island: 'Kalimantan', type: 'Laut', rating: 4.6, stay: 700000, fare: 3000000, desc: 'Berenang bersama ubur-ubur tak menyengat di Danau Kakaban.' },
    { id: 'bunaken', name: 'Bunaken', island: 'Sulawesi', type: 'Laut', rating: 4.6, stay: 650000, fare: 3200000, desc: 'Taman laut dengan dinding karang curam dan penyu hijau.' },
    { id: 'kelimutu', name: 'Danau Kelimutu', island: 'Nusa Tenggara', type: 'Gunung', rating: 4.7, stay: 400000, fare: 3600000, desc: 'Tiga danau kawah yang warnanya berubah dari waktu ke waktu.' },
    { id: 'toraja', name: 'Tana Toraja', island: 'Sulawesi', type: 'Budaya', rating: 4.6, stay: 500000, fare: 2800000, desc: 'Rumah adat tongkonan dan tradisi upacara Rambu Solo.' }
  ];
  const TYPES = {
    Laut: { icon: '🏝️', color: '#0ea5e9' },
    Gunung: { icon: '🌋', color: '#f97316' },
    Danau: { icon: '🏞️', color: '#0284c7' },
    Budaya: { icon: '🛕', color: '#a16207' }
  };
  const DAILY = 300000; // makan & transport lokal per orang per hari
  const STORAGE_KEY = 'jelajah-trip';
  const rupiah = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 });
  const $ = id => document.getElementById(id);
  const findDest = id => dests.find(d => d.id === id);

  let trip = [];
  try {
    trip = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]').filter(t => findDest(t.id));
  } catch (e) {
    trip = [];
  }

  function save() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(trip)); } catch (e) { /* penyimpanan tidak tersedia */ }
  }

  [...new Set(dests.map(d => d.island))].sort().forEach(island => $('island').add(new Option(island)));

  function renderDests() {
    const q = $('q').value.trim().toLowerCase();
    const island = $('island').value;
    const budget = Number($('budget').value) || Infinity;
    const list = dests.filter(d => (!island || d.island === island) && d.stay <= budget &&
      (d.name + d.desc + d.type + d.island).toLowerCase().includes(q));
    $('result-count').textContent = `${list.length} dari ${dests.length} destinasi`;
    $('dests').innerHTML = list.map(d => {
      const inTrip = trip.some(t => t.id === d.id);
      const type = TYPES[d.type];
      return `<article class="dest">
        <div class="pic" style="--c: ${type.color}" aria-hidden="true">${type.icon}</div>
        <div class="body">
          <h3>${d.name}</h3>
          <p class="meta">${d.type} · ${d.island} · ★ ${d.rating}</p>
          <p class="desc">${d.desc}</p>
          <div class="row">
            <span><b>${rupiah.format(d.stay)}</b> <small class="meta">/malam*</small></span>
            <button class="add" data-id="${d.id}" aria-pressed="${inTrip}">${inTrip ? '✓ Ditambahkan' : '+ Rencana'}</button>
          </div>
        </div>
      </article>`;
    }).join('') || '<p class="meta">Tidak ada destinasi yang cocok. Coba longgarkan filter.</p>';
  }

  function renderTrip() {
    $('trip').innerHTML = trip.map(t => {
      const d = findDest(t.id);
      return `<li>
        <div>
          <b>${d.name}</b>
          <div class="nights">
            <button data-dec="${d.id}" aria-label="Kurangi malam di ${d.name}">−</button>
            ${t.nights} malam
            <button data-inc="${d.id}" aria-label="Tambah malam di ${d.name}">+</button>
          </div>
        </div>
        <button class="rm" data-rm="${d.id}" aria-label="Hapus ${d.name} dari rencana">Hapus</button>
      </li>`;
    }).join('');
    $('trip-empty').hidden = trip.length > 0;
    $('share').disabled = !trip.length;

    let day = 1;
    $('itinerary').innerHTML = trip.map(t => {
      const line = `<li>Hari ${day}–${day + t.nights}: ${findDest(t.id).name}</li>`;
      day += t.nights;
      return line;
    }).join('');

    // Rumus perkiraan: kamar berisi 2 orang, tiket PP per orang untuk tiap destinasi,
    // biaya harian per orang untuk (total malam + 1) hari.
    const people = Math.min(10, Math.max(1, Number($('people').value) || 1));
    const nights = trip.reduce((sum, t) => sum + t.nights, 0);
    const rooms = Math.ceil(people / 2);
    const stay = trip.reduce((sum, t) => sum + findDest(t.id).stay * t.nights * rooms, 0);
    const fare = trip.reduce((sum, t) => sum + findDest(t.id).fare, 0) * people;
    const daily = trip.length ? DAILY * people * (nights + 1) : 0;
    const total = stay + fare + daily;

    $('stay-label').textContent = `Penginapan (${nights} malam, ${rooms} kamar)`;
    $('fare-label').textContent = `Tiket pesawat (${people} orang)`;
    $('stay').textContent = rupiah.format(stay);
    $('fare').textContent = rupiah.format(fare);
    $('daily').textContent = rupiah.format(daily);
    $('total').textContent = rupiah.format(total);
    $('per-person').textContent = rupiah.format(total / people);
  }

  // Daftar digambar ulang, jadi fokus keyboard dikembalikan ke tombol yang sama.
  function update(focusSelector) {
    save();
    renderDests();
    renderTrip();
    document.querySelector(focusSelector)?.focus();
  }

  $('dests').addEventListener('click', e => {
    const button = e.target.closest('.add');
    if (!button) return;
    const id = button.dataset.id;
    if (trip.some(t => t.id === id)) trip = trip.filter(t => t.id !== id);
    else trip.push({ id, nights: 2 });
    update(`.add[data-id="${id}"]`);
  });

  $('trip').addEventListener('click', e => {
    const { inc, dec, rm } = e.target.dataset;
    const item = trip.find(t => t.id === (inc || dec || rm));
    if (!item) return;
    if (inc) item.nights = Math.min(14, item.nights + 1);
    if (dec) item.nights = Math.max(1, item.nights - 1);
    if (rm) trip = trip.filter(t => t !== item);
    update(inc ? `[data-inc="${inc}"]` : dec ? `[data-dec="${dec}"]` : '#people');
  });

  $('finder').addEventListener('submit', e => e.preventDefault());
  $('finder').addEventListener('input', renderDests);
  $('people').addEventListener('input', renderTrip);

  $('share').addEventListener('click', async () => {
    const stops = trip.map(t => `${findDest(t.id).name} (${t.nights} malam)`).join(' → ');
    const text = `Rencana liburan: ${stops}. Perkiraan total ${$('total').textContent} untuk ${$('people').value} orang.`;
    try {
      await navigator.clipboard.writeText(text);
      $('share-status').textContent = 'Ringkasan disalin ke clipboard.';
    } catch (e) {
      $('share-status').textContent = text;
    }
  });

  renderDests();
  renderTrip();
</script>
</body>
</html>
```

**Cek kebutuhan**
- **Daftar destinasi** → 10 destinasi di `dests`, tersebar dari Sumatera sampai Papua, masing-masing dengan jenis (laut, gunung, danau, budaya), rating, harga menginap per malam, dan tiket pesawat pulang-pergi dari Jakarta.
- **Cari dan filter per pulau dan budget** → `renderDests()` berjalan setiap kali form `#finder` berubah. Kolom cari mencocokkan nama, deskripsi, jenis, dan pulau. Pilihan pulau dibuat dari data, dan budget menyaring harga menginap maksimal Rp500 ribu, Rp1 juta, atau Rp2 juta per malam.
- **Masukkan ke rencana perjalanan** → tombol "+ Rencana" (`aria-pressed`) menambah atau mengeluarkan destinasi. Rencana dimulai dengan 2 malam per destinasi.
- **Jumlah malam bisa diatur** → tombol − dan + per destinasi, antara 1 dan 14 malam. `#itinerary` menyusun urutan harinya, misalnya "Hari 1–3: Raja Ampat".
- **Estimasi biaya untuk beberapa orang** → `renderTrip()` menghitung:
  - kamar = jumlah orang ÷ 2, dibulatkan ke atas;
  - penginapan = harga per malam × malam × kamar;
  - tiket = tiket × orang;
  - uang harian Rp300.000 × orang × (total malam + 1).
  Total dan biaya per orang diformat dengan `Intl.NumberFormat('id-ID')`.
- **Salin untuk dikirim ke teman** → "Salin Ringkasan" memakai `navigator.clipboard.writeText()`. Jika diblokir, teks ringkasannya ditampilkan supaya bisa disalin manual.
- **Rencana tidak hilang** → `save()` menyimpan `trip` ke `localStorage` di dalam `try/catch`, dan id destinasi yang tidak dikenal dibuang saat dimuat.

Setelah daftar digambar ulang, fokus keyboard dikembalikan ke tombol yang baru ditekan, jadi pengguna keyboard tidak kehilangan posisi.

