  .plus { position: absolute; left: 50%; top: 20px; transform: translateX(-50%); font-weight: 800; color: var(--text); animation: up .8s forwards; pointer-events: none; }
  @keyframes up { to { top: -30px; opacity: 0; } }
  .row { display: flex; justify-content: space-between; align-items: center; gap: 10px; margin-bottom: 16px; }
  .row p { font-size: .9rem; }
  .btns { display: flex; gap: 6px; }
  button { font: inherit; }
  .btn { background: #8f7a66; color: #fff; border: 0; border-radius: 10px; padding: 10px 14px; font-weight: 700; cursor: pointer; white-space: nowrap; }
  .btn:disabled { opacity: .45; cursor: default; }
  .board { position: relative; width: var(--size); height: var(--size); background: var(--board); border-radius: 14px; padding: var(--gap); touch-action: none; user-select: none; }
  .grid, .tiles { position: absolute; inset: var(--gap); }
