  .tile { position: absolute; width: calc((100% - 3 * var(--gap)) / 4); height: calc((100% - 3 * var(--gap)) / 4); border-radius: 8px; display: grid; place-items: center; font-weight: 900; transition: transform .12s ease-in-out; font-size: clamp(1.3rem, 7vw, 2.6rem); }
  .tile .in { width: 100%; height: 100%; display: grid; place-items: center; border-radius: 8px; flex-direction: column; line-height: 1; }
