<body>
<div class="wrap">
  <div class="top">
    <h1>2048</h1>
    <div class="scores">
      <div class="score" id="score-box"><small>Skor</small><b id="score">0</b></div>
      <div class="score"><small>Terbaik</small><b id="best">0</b></div>
    </div>
  </div>
  <div class="row">
    <p>Gabungkan rempah sampai <b>2048 · Emas Hitam</b>!</p>
    <div class="btns"><button class="btn" id="undo" disabled aria-label="Urungkan langkah" title="Urungkan (Ctrl+Z)">↶</button><button class="btn" id="new">Baru</button></div>
  </div>
  <div class="board" id="board">
    <div class="grid">
      <div></div><div></div><div></div><div></div><div></div><div></div><div></div><div></div>
      <div></div><div></div><div></div><div></div><div></div><div></div><div></div><div></div>
    </div>
    <div class="tiles" id="tiles"></div>
    <div class="overlay" id="overlay"><h2 id="ov-title"></h2><p id="ov-text"></p><div class="btns"><button class="btn" id="ov-continue">Lanjut Main</button><button class="btn" id="ov-new">Main Lagi</button></div></div>
  </div>
  <div class="help">
    <b>Cara main:</b> gunakan tombol panah / WASD, atau geser layar. Ubin dengan angka sama akan bergabung saat bersentuhan.
    <div class="legend" id="legend"></div>
  </div>
</div>

<script>
  const NAMES = { 2: 'Garam', 4: 'Merica', 8: 'Kunyit', 16: 'Jahe', 32: 'Kencur', 64: 'Lengkuas', 128: 'Kayu Manis', 256: 'Cengkih', 512: 'Kapulaga', 1024: 'Pala', 2048: 'Emas Hitam', 4096: 'Raja Rempah' };
  const COLORS = { 2: ['#eee4da', '#776e65'], 4: ['#ede0c8', '#776e65'], 8: ['#f2b179', '#fff'], 16: ['#f59563', '#fff'], 32: ['#f67c5f', '#fff'], 64: ['#f65e3b', '#fff'],
    128: ['#edcf72', '#fff'], 256: ['#edcc61', '#fff'], 512: ['#edc850', '#fff'], 1024: ['#c2a03c', '#fff'], 2048: ['#3c3a32', '#f9d65c'], 4096: ['#1f1d18', '#ffd700'] };
  const N = 4;
  let grid, score, bestScore = 0, history = [], won = false, keepGoing = false, idSeq = 1;
  try { bestScore = +localStorage.getItem('2048-best') || 0; } catch (e) {}

  const tilesEl = document.getElementById('tiles');
  const tileEls = new Map();

  function empty() { return Array.from({ length: N }, () => Array(N).fill(null)); }

  function addRandom() {
    const cells = [];
    grid.forEach((row, r) => row.forEach((c, k) => { if (!c) cells.push([r, k]); }));
    if (!cells.length) return;
    const [r, c] = cells[Math.floor(Math.random() * cells.length)];
    grid[r][c] = { id: idSeq++, v: Math.random() < .9 ? 2 : 4, isNew: true };
  }

  function newGame() {
    tileEls.forEach(el => el.remove()); tileEls.clear();
    grid = empty(); score = 0; history = []; won = false; keepGoing = false;
    addRandom(); addRandom();
    document.getElementById('overlay').classList.remove('show');
    render();
  }

  // Geser satu baris ke kiri; dipakai untuk keempat arah dengan memutar koordinat.
  function slideLine(line) {
    const tiles = line.filter(Boolean);
    const out = [];
    let gained = 0;
    for (let i = 0; i < tiles.length; i++) {
      if (i + 1 < tiles.length && tiles[i].v === tiles[i + 1].v) {
        const v = tiles[i].v * 2;
        out.push({ id: idSeq++, v, merged: true, from: [tiles[i].id, tiles[i + 1].id] });
        gained += v; i++;
      } else out.push({ ...tiles[i], merged: false, isNew: false });
    }
    while (out.length < N) out.push(null);
    return { out, gained };
  }

  function move(dir) {
    if (document.getElementById('overlay').classList.contains('show')) return;
    const coords = (i, j) => dir === 'left' ? [i, j] : dir === 'right' ? [i, N - 1 - j] : dir === 'up' ? [j, i] : [N - 1 - j, i];
    const snapshot = JSON.stringify({ grid, score });
    const next = empty();
    let moved = false, gained = 0;
    for (let i = 0; i < N; i++) {
      const line = [];
      for (let j = 0; j < N; j++) { const [r, c] = coords(i, j); line.push(grid[r][c]); }
      const res = slideLine(line);
      gained += res.gained;
      res.out.forEach((t, j) => {
        const [r, c] = coords(i, j);
        next[r][c] = t;
        if ((t && !line[j]) || (t && line[j] && t.id !== line[j].id)) moved = true;
      });
    }
    if (!moved) return;
    history.push(snapshot);
    if (history.length > 20) history.shift();
    grid = next;
    score += gained;
    if (gained) showPlus(gained);
    addRandom();
    render();
    checkEnd();
  }

  function canMove() {
    for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) {
      if (!grid[r][c]) return true;
      if (c < N - 1 && grid[r][c + 1] && grid[r][c + 1].v === grid[r][c].v) return true;
      if (r < N - 1 && grid[r + 1][c] && grid[r + 1][c].v === grid[r][c].v) return true;
    }
    return false;
  }

  function checkEnd() {
    const max = Math.max(...grid.flat().filter(Boolean).map(t => t.v));
    if (max >= 2048 && !won && !keepGoing) {
      won = true;
      overlay('Kamu menang! 🏆', 'Kamu mendapatkan Emas Hitam. Mau lanjut mengejar Raja Rempah?', true);
    } else if (!canMove()) overlay('Permainan selesai', `Skor akhir ${score}. Coba lagi?`, false);
  }
  function overlay(title, text, canContinue) {
    document.getElementById('ov-title').textContent = title;
    document.getElementById('ov-text').textContent = text;
    document.getElementById('ov-continue').style.display = canContinue ? '' : 'none';
    document.getElementById('overlay').classList.add('show');
  }

  function render() {
    const seen = new Set();
    grid.forEach((row, r) => row.forEach((t, c) => {
      if (!t) return;
      seen.add(t.id);
      let el = tileEls.get(t.id);
      if (!el) {
        el = document.createElement('div');
        el.className = 'tile' + (t.isNew ? ' new' : '') + (t.merged ? ' merged' : '');
        const [bg, fg] = COLORS[t.v] || COLORS[4096];
        el.innerHTML = `<div class="in" style="background:${bg};color:${fg}"><span style="font-size:${t.v >= 1024 ? '.7em' : t.v >= 128 ? '.85em' : '1em'}">${t.v}</span><small>${NAMES[t.v] || ''}</small></div>`;
        el.dataset.value = t.v;
        tilesEl.appendChild(el);
        tileEls.set(t.id, el);
        // Ubin hasil gabungan muncul dari posisi ubin asalnya supaya terlihat menyatu
        if (t.merged) t.from.forEach(fid => { const old = tileEls.get(fid); if (old) { old.style.transform = pos(r, c); old.style.zIndex = 0; } });
      }
      el.style.transform = pos(r, c);
      el.style.zIndex = 1;
      t.isNew = false;
    }));
    tileEls.forEach((el, id) => {
      if (!seen.has(id)) { tileEls.delete(id); setTimeout(() => el.remove(), 130); }
    });
    document.getElementById('score').textContent = score;
    if (score > bestScore) { bestScore = score; try { localStorage.setItem('2048-best', bestScore); } catch (e) {} }
    document.getElementById('best').textContent = bestScore;
    document.getElementById('undo').disabled = !history.length;
  }
  const pos = (r, c) => `translate(calc(${c} * (100% + var(--gap))), calc(${r} * (100% + var(--gap))))`;

  function showPlus(n) {
    const p = document.createElement('span');
    p.className = 'plus'; p.textContent = '+' + n;
    document.getElementById('score-box').appendChild(p);
    setTimeout(() => p.remove(), 800);
  }

  function undo() {
    if (!history.length) return;
    const s = JSON.parse(history.pop());
    tileEls.forEach(el => el.remove()); tileEls.clear();
    grid = s.grid.map(row => row.map(t => t && { ...t, isNew: false, merged: false }));
    score = s.score;
    document.getElementById('overlay').classList.remove('show');
    render();
  }

  const KEYS = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down', a: 'left', d: 'right', w: 'up', s: 'down' };
  document.addEventListener('keydown', e => {
    const dir = KEYS[e.key] || KEYS[e.key.toLowerCase()];
    if (dir) { e.preventDefault(); move(dir); }
    if ((e.ctrlKey || e.metaKey) && e.key === 'z') { e.preventDefault(); undo(); }
  });
  let touch = null;
  const board = document.getElementById('board');
  board.addEventListener('pointerdown', e => { touch = [e.clientX, e.clientY]; });
  board.addEventListener('pointerup', e => {
    if (!touch) return;
    const dx = e.clientX - touch[0], dy = e.clientY - touch[1];
    touch = null;
    if (Math.max(Math.abs(dx), Math.abs(dy)) < 24) return;
    move(Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : (dy > 0 ? 'down' : 'up'));
  });
  document.getElementById('new').addEventListener('click', newGame);
  document.getElementById('ov-new').addEventListener('click', newGame);
  document.getElementById('ov-continue').addEventListener('click', () => { keepGoing = true; document.getElementById('overlay').classList.remove('show'); });
  document.getElementById('undo').addEventListener('click', undo);

  document.getElementById('legend').innerHTML = Object.entries(NAMES).slice(0, 11).map(([v, n]) => `<span style="background:${COLORS[v][0]};color:${COLORS[v][1]}">${v} ${n}</span>`).join('');
  newGame();
</script>
</body>
</html>
```

**Cek kebutuhan**
- **Angka bernama rempah** → objek `NAMES`, mulai dari 2 Garam sampai 2048 Emas Hitam dan 4096 Raja Rempah. Nama tampil di bawah angka setiap ubin dan di legenda.
- **Main pakai keyboard** → peta `KEYS`: tombol panah dan WASD memanggil `move()`.
- **Geser di HP** → `pointerdown`/`pointerup` di papan. Geseran di bawah 24px diabaikan, dan arahnya diambil dari sumbu yang lebih panjang.
- **Animasi geser dan gabung** → setiap ubin punya `id` tetap dan dipindah dengan `transform`, jadi CSS menganimasikan perpindahannya. Dua ubin asal meluncur ke posisi gabungan dulu sebelum dihapus, lalu ubin baru muncul dengan kelas `merged`.
- **Skor dan skor terbaik** → nilai hasil gabungan ditambahkan ke skor, dengan efek `+n` dari `showPlus()`. Skor terbaik disimpan di `localStorage` (dibungkus `try/catch`).
- **Undo** → `history` menyimpan sampai 20 keadaan papan. Tombol ↶ atau Ctrl+Z memanggil `undo()`.
- **Pesan menang/kalah** → `checkEnd()` menampilkan overlay "Kamu menang!" saat ubin 2048 muncul, dengan pilihan lanjut main. Overlay "Permainan selesai" muncul bila `canMove()` tidak menemukan sel kosong maupun pasangan bertetangga.

Aturan geser ditulis sekali di `slideLine()` untuk arah kiri. Tiga arah lain memakai fungsi yang sama dengan memutar koordinat di `move()`, jadi aturan "satu ubin hanya bergabung sekali per langkah" berlaku sama di semua arah.

