<script>
  const services = [
    { id: 'periksa', ic: '🔍', name: 'Pemeriksaan & Konsultasi', price: 100000, dur: 30 },
    { id: 'scaling', ic: '✨', name: 'Scaling Karang Gigi', price: 350000, dur: 45 },
    { id: 'behel', ic: '😁', name: 'Behel / Ortodonti', price: 6500000, dur: 60 },
    { id: 'anak', ic: '🧸', name: 'Perawatan Gigi Anak', price: 150000, dur: 30 }
  ];
  // days: hari praktik, 0 = Minggu … 6 = Sabtu
  const doctors = [
    { id: 'ayu', name: 'drg. Ayu Pratiwi', spec: 'Dokter Gigi Umum', days: [1, 2, 3, 4, 5], skills: ['periksa', 'scaling'] },
    { id: 'reza', name: 'drg. Reza Mahendra, Sp.Ort', spec: 'Spesialis Ortodonti', days: [2, 4, 6], skills: ['periksa', 'behel'] },
    { id: 'nadia', name: 'drg. Nadia Putri, Sp.KGA', spec: 'Spesialis Gigi Anak', days: [1, 3, 5, 6], skills: ['periksa', 'anak'] }
  ];
  const DAYS = ['Min', 'Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab'];
  const SLOTS = ['09:00', '10:00', '11:00', '13:00', '14:00', '15:00', '16:00', '19:00'];
  const $ = id => document.getElementById(id);
  const rp = n => 'Rp' + n.toLocaleString('id-ID');
  const practice = d => 'Praktik ' + d.days.map(i => DAYS[i]).join(', ');

  // Markup dibuat dari data tetap di atas, bukan dari input pengguna
  $('services').innerHTML = services.map(s => `
    <article class="card"><h3>${s.ic} ${s.name}</h3>
      <small>± ${s.dur} menit</small><p>mulai <b>${rp(s.price)}</b></p></article>`).join('');
  $('doctors').innerHTML = doctors.map(d => `
    <article class="card"><h3>${d.name}</h3><small>${d.spec}</small>
      <p class="days">${practice(d)}</p></article>`).join('');

  const state = { step: 1, svc: null, doc: null, date: null, time: null };

  // Simulasi slot terisi: tetap (deterministik) per tanggal, dokter, dan jam
  function taken(date, docId, slot) {
    return (date.getDate() * 31 + docId.length * 7 + SLOTS.indexOf(slot) * 13) % 5 === 0;
  }

  function choice(cls, key, value, selected, label, disabled = false) {
    return `<button type="button" class="${cls}" data-${key}="${value}" aria-pressed="${selected}"${disabled ? ' disabled' : ''}>${label}</button>`;
  }

  function renderStep() {
    if (state.step === 1) {
      $('svc-list').innerHTML = services.map(s => choice('opt', 'svc', s.id, state.svc === s.id,
        `<span>${s.ic} <b>${s.name}</b></span>${rp(s.price)}`)).join('');
    }
    if (state.step === 2) {
      $('doc-list').innerHTML = doctors.filter(d => d.skills.includes(state.svc)).map(d => choice('opt', 'doc', d.id, state.doc === d.id,
        `<span><b>${d.name}</b><small>${d.spec} · ${practice(d)}</small></span>`)).join('');
    }
    if (state.step === 3) renderSchedule();
    if (state.step === 4) $('summary').innerHTML = summaryHTML();
  }

  // Tujuh hari ke depan; tanggal di luar hari praktik dokter dinonaktifkan
  function renderSchedule() {
    const doc = doctors.find(d => d.id === state.doc);
    const now = new Date();
    let html = '';
    for (let i = 1; i <= 7; i++) {
      const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() + i);
      html += choice('date', 'date', d.getTime(), state.date?.getTime() === d.getTime(),
        `${DAYS[d.getDay()]}<b>${d.getDate()}</b>`, !doc.days.includes(d.getDay()));
    }
    $('dates').innerHTML = html;
    $('slots').innerHTML = state.date
      ? SLOTS.map(s => choice('slot', 'time', s, state.time === s, s, taken(state.date, doc.id, s))).join('')
      : '<p class="note" style="grid-column: 1 / -1">Pilih tanggal dulu. Tanggal dicoret: dokter tidak praktik.</p>';
  }

  function summaryHTML() {
    const s = services.find(x => x.id === state.svc);
    const d = doctors.find(x => x.id === state.doc);
    const when = state.date.toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long' });
    return `<div><dt>Layanan</dt><dd>${s.name}</dd></div><div><dt>Dokter</dt><dd>${d.name}</dd></div>
      <div><dt>Jadwal</dt><dd>${when}, ${state.time}</dd></div><div><dt>Estimasi biaya</dt><dd>${rp(s.price)}</dd></div>`;
  }

  function go(step, moveFocus = true) {
    state.step = step;
    document.querySelectorAll('.step').forEach(el => { el.hidden = +el.dataset.step !== step; });
    [...$('steps-ind').children].forEach((el, i) => {
      el.classList.toggle('on', i < step);
      el.toggleAttribute('aria-current', i === step - 1);
    });
    renderStep();
    $('back').hidden = step === 1 || step === 5;
    $('next').textContent = step === 4 ? 'Konfirmasi' : step === 5 ? 'Reservasi Baru' : 'Lanjut →';
    updateNext();
    if (moveFocus) document.querySelector(`.step[data-step="${step}"] h3`).focus();
  }

  function updateNext() {
    const ready = { 1: state.svc, 2: state.doc, 3: state.date && state.time }[state.step];
    $('next').disabled = state.step < 4 && !ready;
  }

  // Menerima 08…, 628…, atau +628… lalu 8–11 digit; spasi dan tanda hubung diabaikan
  function validWA(raw) {
    return /^(\+62|62|0)8\d{8,11}$/.test(raw.replace(/[\s-]/g, ''));
  }

  function showError(input, errEl, message) {
    errEl.textContent = message;
    input.setAttribute('aria-invalid', message ? 'true' : 'false');
  }

  $('panel').addEventListener('click', e => {
    const b = e.target.closest('button[data-svc], button[data-doc], button[data-date], button[data-time]');
    if (!b) return;
    const { svc, doc, date, time } = b.dataset;
    // Mengganti pilihan di langkah awal mengosongkan pilihan sesudahnya
    if (svc && svc !== state.svc) Object.assign(state, { svc, doc: null, date: null, time: null });
    if (doc && doc !== state.doc) Object.assign(state, { doc, date: null, time: null });
    if (date) Object.assign(state, { date: new Date(+date), time: null });
    if (time) state.time = time;
    renderStep();
    updateNext();
  });

  $('back').addEventListener('click', () => go(state.step - 1));

  $('next').addEventListener('click', () => {
    if (state.step === 4) {
      const name = $('p-name').value.trim();
      showError($('p-name'), $('e-name'), name.length >= 3 ? '' : 'Isi nama lengkap (minimal 3 huruf).');
      showError($('p-phone'), $('e-phone'), validWA($('p-phone').value) ? '' : 'Nomor WhatsApp tidak valid. Contoh: 081234567890');
      if ($('e-name').textContent || $('e-phone').textContent) return;
      $('code').textContent = 'SS-' + Math.random().toString(36).slice(2, 7).toUpperCase();
      $('summary-final').innerHTML = '<div><dt>Pasien</dt><dd></dd></div>' + summaryHTML();
      $('summary-final').querySelector('dd').textContent = name;
      return go(5);
    }
    if (state.step === 5) {
      Object.assign(state, { svc: null, doc: null, date: null, time: null });
      ['p-name', 'p-phone', 'p-note'].forEach(id => { $(id).value = ''; });
      return go(1);
    }
    go(state.step + 1);
  });

  $('menu-btn').addEventListener('click', () => {
    const open = $('menu').classList.toggle('open');
    $('menu-btn').setAttribute('aria-expanded', open);
  });
  $('menu').addEventListener('click', e => {
    if (e.target.tagName !== 'A') return;
    $('menu').classList.remove('open');
    $('menu-btn').setAttribute('aria-expanded', 'false');
  });

  $('yr').textContent = new Date().getFullYear();
  go(1, false);
</script>
</body>
</html>
```

**Cek kebutuhan**
- **Layanan dan kisaran harga** → array `services` berisi 4 layanan dengan durasi dan harga "mulai Rp…" dari `rp()`.
- **Jadwal praktik dokter** → setiap dokter di `doctors` punya `days` (0 = Minggu) dan `skills`. Kartu dokter menampilkan hari praktik dari `practice()`.
- **Reservasi 4 langkah** → `go(step)` menampilkan satu `.step` sekaligus, dan `#steps-ind` menandai langkah aktif dengan `aria-current`. `updateNext()` menonaktifkan tombol Lanjut sampai pilihan langkah itu terisi, dan mengganti pilihan di awal mengosongkan pilihan sesudahnya.
  - Langkah 2 hanya menampilkan dokter yang menangani layanan terpilih.
  - Langkah 3 berisi 7 tanggal mulai besok. Hari dokter tidak praktik dinonaktifkan, dan slot yang sudah terisi disimulasikan oleh `taken()` dengan hasil yang tetap.
- **Validasi nomor WhatsApp** → `validWA()` membuang spasi dan tanda hubung, lalu menerima awalan 08, 628, atau +628 dengan total 10–13 digit (format 08). Pesan galat dipasang lewat `showError()` dengan `aria-invalid`.
- **Konfirmasi** → ringkasan reservasi dan kode `SS-XXXXX`. Nama pasien dipasang dengan `textContent`.
- **FAQ** → tiga `<details>`/`<summary>` yang bisa dibuka dengan keyboard tanpa JavaScript.

**Catatan hukum**
- Isi website tidak memuat testimoni pasien, klaim "terbaik", atau janji hasil perawatan. Ini sejalan dengan Permenkes No. 1787/MENKES/PER/XII/2010 tentang Iklan dan Publikasi Pelayanan Kesehatan.
- Keluhan pasien termasuk data kesehatan, yaitu data pribadi yang bersifat spesifik (Pasal 4 ayat (2) UU No. 27 Tahun 2022 tentang Pelindungan Data Pribadi). Saat form dihubungkan ke server, kirim lewat HTTPS dan tambahkan persetujuan eksplisit beserta tujuan pemrosesannya.

