<script>
  const $ = (id) => document.getElementById(id);
  const rp = (n) => 'Rp' + Math.round(n).toLocaleString('id-ID');
  const jamSekarang = () => new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });

  // Demo absen: catat masuk/pulang, simpan 3 entri terakhir
  let clockedIn = false;
  $('clockin').addEventListener('click', () => {
    clockedIn = !clockedIn;
    const item = document.createElement('li');
    const label = document.createElement('span');
    const time = document.createElement('b');
    label.textContent = clockedIn ? 'Masuk' : 'Pulang';
    time.textContent = jamSekarang();
    item.append(label, time);
    $('log').prepend(item);
    while ($('log').children.length > 3) $('log').lastElementChild.remove();
    $('clockin').textContent = clockedIn ? 'Pulang' : 'Masuk';
    $('clockin').classList.toggle('out', clockedIn);
  });

  // Formulir pendaftaran
  $('signup').addEventListener('submit', (e) => {
    e.preventDefault();
    const email = $('email').value.trim();
    const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    $('form-msg').style.color = ok ? 'var(--green)' : 'var(--red)';
    $('form-msg').textContent = ok
      ? `Tautan aktivasi dikirim ke ${email}`
      : 'Masukkan alamat email yang valid.';
    if (ok) $('email').value = '';
  });

  // Tab fitur
  const FEATURES = [
    {
      tab: 'Absensi',
      title: 'Absen dengan GPS',
      desc: 'Karyawan hanya bisa absen di radius lokasi kerja, jadi tidak ada titip absen.',
      points: ['Atur radius per cabang', 'Mode offline', 'Shift dan lembur fleksibel'],
      rows: [['Rina', '07:52 · Tepat waktu'], ['Agus', '08:14 · Terlambat'], ['Hadir hari ini', '23 / 25']]
    },
    {
      tab: 'Cuti',
      title: 'Pengajuan cuti tanpa kertas',
      desc: 'Karyawan mengajukan dari HP, atasan menyetujui dengan satu ketukan.',
      points: ['Saldo cuti otomatis', 'Persetujuan bertingkat', 'Kalender tim'],
      rows: [['Dewi, 20–22 Okt', 'Disetujui'], ['Fajar, 28 Okt', 'Menunggu'], ['Sisa cuti Anda', '9 hari']]
    },
    {
      tab: 'Payroll',
      title: 'Gaji, BPJS, dan PPh 21 sekali klik',
      desc: 'Potongan BPJS dan PPh 21 dihitung otomatis dari data absensi.',
      points: ['Slip gaji digital', 'Transfer massal', 'Laporan pajak'],
      rows: [['Gaji pokok', 'Rp5.200.000'], ['Lembur 6 jam', 'Rp270.000'], ['Potongan BPJS', '−Rp208.000'], ['PPh 21 (TER)', '−Rp28.530'], ['Diterima', 'Rp5.233.470']]
    }
  ];

  function showFeature(index) {
    const f = FEATURES[index];
    $('feature').innerHTML = `
      <div>
        <h3>${f.title}</h3>
        <p>${f.desc}</p>
        <ul>${f.points.map((p) => `<li>${p}</li>`).join('')}</ul>
      </div>
      <div class="visual">
        ${f.rows.map(([k, v]) => `<div class="vrow"><span>${k}</span><span>${v}</span></div>`).join('')}
      </div>`;
    [...$('tabs').children].forEach((tab, i) => tab.setAttribute('aria-selected', i === index));
  }

  $('tabs').innerHTML = FEATURES
    .map((f, i) => `<button class="tab" role="tab" aria-controls="feature" data-i="${i}">${f.tab}</button>`)
    .join('');
  $('tabs').addEventListener('click', (e) => {
    const tab = e.target.closest('.tab');
    if (tab) showFeature(Number(tab.dataset.i));
  });
  showFeature(0);

  // Kalkulator penghematan
  function hitungHemat() {
    const emp = Number($('emp').value);
    const minutes = Number($('min').value);
    const salary = Number($('sal').value);
    const hoursSaved = (emp * minutes / 60) * 0.85 * 12; // jam per tahun
    const hourlyWage = salary / 173; // 173 jam kerja per bulan
    $('v-emp').textContent = emp;
    $('v-min').textContent = minutes + ' menit';
    $('v-sal').textContent = rp(salary);
    $('save').textContent = rp(hoursSaved * hourlyWage);
    $('save-sub').textContent = `≈ ${Math.round(hoursSaved)} jam kerja admin per tahun`;
  }
  ['emp', 'min', 'sal'].forEach((id) => $(id).addEventListener('input', hitungHemat));
  hitungHemat();

  // Harga: tahunan diskon 20%
  const PLANS = [
    { name: 'Starter', price: 0, desc: 'Hingga 5 karyawan', feats: ['Absensi GPS', 'Pengajuan cuti', '1 lokasi kerja'] },
    { name: 'Bisnis', price: 15000, desc: 'Untuk usaha yang tumbuh', feats: ['Semua fitur Starter', 'Payroll, BPJS, PPh 21', 'Hingga 10 lokasi'], pop: true },
    { name: 'Korporat', price: 25000, desc: 'Untuk banyak cabang', feats: ['Semua fitur Bisnis', 'Lokasi tak terbatas', 'Integrasi API'] }
  ];
  let yearly = false;

  function renderPlans() {
    $('plans').innerHTML = PLANS.map((p) => {
      const price = yearly ? p.price * 0.8 : p.price;
      const note = yearly && price ? `Ditagih ${rp(price * 12)} per karyawan per tahun` : '';
      return `
        <article class="plan ${p.pop ? 'pop' : ''}">
          <h3>${p.name}</h3>
          <small class="muted">${p.desc}</small>
          <div class="price">${price ? `${rp(price)}<small> /karyawan/bln</small>` : 'Gratis'}</div>
          <small class="muted">${note}</small>
          <ul>${p.feats.map((f) => `<li>${f}</li>`).join('')}</ul>
          <a class="btn ${p.pop ? 'btn-p' : ''}" href="#daftar">Pilih ${p.name}</a>
        </article>`;
    }).join('');
  }

  $('billing').addEventListener('click', () => {
    yearly = !yearly;
    $('billing').setAttribute('aria-pressed', yearly);
    renderPlans();
  });
  renderPlans();

  $('yr').textContent = new Date().getFullYear();
</script>
</body>
</html>
```

**Cek kebutuhan**
- **Demo tombol absen** → `#clockin` bergantian mencatat "Masuk" dan "Pulang" beserta jam dari `toLocaleTimeString('id-ID')` ke `#log`. Hanya tiga catatan terakhir yang disimpan.
- **Tab fitur** → `FEATURES` berisi Absensi, Cuti, dan Payroll. `showFeature()` mengisi panel dan mengatur `aria-selected`, dengan `role="tablist"`, `role="tab"`, dan `role="tabpanel"`.
- **Kalkulator penghematan** → `hitungHemat()` berjalan setiap slider digeser. Rumusnya: jam hemat per tahun = karyawan × menit rekap per bulan ÷ 60 × 85% × 12, lalu dikali upah per jam (gaji admin ÷ 173). Dengan nilai bawaan (25 karyawan, 20 menit, gaji Rp5.000.000) hasilnya ±85 jam atau Rp2.456.647 per tahun.
- **Harga bulanan/tahunan** → `#billing` membalik `yearly` dan mengatur `aria-pressed`. Pada mode tahunan, `renderPlans()` memakai harga × 0,8 dan menampilkan tagihan per tahun, misalnya Bisnis Rp12.000 × 12 = Rp144.000 per karyawan.
- **FAQ** → `<details>`/`<summary>` bawaan HTML, jadi bisa dibuka dengan keyboard tanpa JavaScript.
- **Form daftar dengan email** → `#signup` memeriksa format email. Pesan galat atau konfirmasinya muncul di `#form-msg` (`role="status"`), dan alamat yang diketik dipasang dengan `textContent`.

Angka 173 jam per bulan mengikuti pembagi upah sejam di Pasal 31 PP No. 35 Tahun 2021.

**Catatan slip gaji contoh (tab Payroll):**
- **Potongan BPJS** adalah iuran pekerja 4% (JHT 2%, JP 1%, BPJS Kesehatan 1%).
- **PPh 21** memakai TER kategori A sebesar 0,5% (PP 58/2023 dan PMK 168/2023), dari bruto yang sudah termasuk premi JKK, JKM, dan BPJS Kesehatan yang dibayar perusahaan.

