  const cv = document.getElementById('canvas'), ctx = cv.getContext('2d', { willReadFrequently: true });
  let tool = 'pen', color = COLORS[0], size = 6, opacity = 1, bg = 'plain';
  let drawing = false, start = null, last = null, snapshot = null, points = [];
  const undoStack = [], redoStack = [];
  const DPR = Math.min(window.devicePixelRatio || 1, 2);
