    undoStack.push(ctx.getImageData(0, 0, cv.width, cv.height));
    if (undoStack.length > 30) undoStack.shift();
    redoStack.length = 0;
    updateButtons();
  }
  function updateButtons() {
    document.getElementById('undo').disabled = !undoStack.length;
    document.getElementById('redo').disabled = !redoStack.length;
  }
  function undo() { if (!undoStack.length) return; redoStack.push(ctx.getImageData(0, 0, cv.width, cv.height)); ctx.putImageData(undoStack.pop(), 0, 0); updateButtons(); }
  function redo() { if (!redoStack.length) return; undoStack.push(ctx.getImageData(0, 0, cv.width, cv.height)); ctx.putImageData(redoStack.pop(), 0, 0); updateButtons(); }

  const pos = e => { const r = cv.getBoundingClientRect(); return { x: (e.clientX - r.left) * W / r.width, y: (e.clientY - r.top) * H / r.height, p: e.pressure || .5 }; };

