    saveState();
    if (tool === 'fill') { floodFill(Math.floor(p.x * DPR), Math.floor(p.y * DPR)); return; }
    drawing = true; start = last = p; points = [p];
    snapshot = ctx.getImageData(0, 0, cv.width, cv.height);
