  cv.addEventListener('pointercancel', end);
  cv.addEventListener('pointerleave', () => { document.getElementById('status').textContent = 'Gambar dengan mouse, pena, atau jari'; });

  // Ember cat: flood fill berbasis tumpukan dengan toleransi warna kecil
  function floodFill(x, y) {
    const img = ctx.getImageData(0, 0, cv.width, cv.height), d = img.data, w = cv.width, h = cv.height;
    const i0 = (y * w + x) * 4, target = [d[i0], d[i0 + 1], d[i0 + 2], d[i0 + 3]];
    const c = parseInt(color.slice(1), 16), fill = [c >> 16 & 255, c >> 8 & 255, c & 255, Math.round(opacity * 255)];
    const same = i => Math.abs(d[i] - target[0]) + Math.abs(d[i + 1] - target[1]) + Math.abs(d[i + 2] - target[2]) + Math.abs(d[i + 3] - target[3]) < 48;
    if (fill.every((v, k) => Math.abs(v - target[k]) < 3)) return;
    const seen = new Uint8Array(w * h), stack = [x, y];
    while (stack.length) {
      const py = stack.pop(), px = stack.pop();
      if (px < 0 || py < 0 || px >= w || py >= h) continue;
      const k = py * w + px;
      if (seen[k] || !same(k * 4)) continue;
      seen[k] = 1;
      d.set(fill, k * 4);
      stack.push(px + 1, py, px - 1, py, px, py + 1, px, py - 1);
    }
    ctx.putImageData(img, 0, 0);
  }

  // Palet & kontrol
  const swEl = document.getElementById('swatches');
  swEl.innerHTML = COLORS.map((c, i) => `<button class="sw ${i ? '' : 'on'}" style="background:${c}" data-c="${c}" aria-label="Warna ${c}"></button>`).join('');
  swEl.addEventListener('click', e => { const b = e.target.closest('.sw'); if (b) setColor(b.dataset.c); });
  document.getElementById('custom').addEventListener('input', e => setColor(e.target.value));
  function setColor(c) {
    color = c;
    [...swEl.children].forEach(b => b.classList.toggle('on', b.dataset.c === c));
    if (tool === 'eraser') setTool('pen');
    preview();
  }
  function setTool(t) {
    tool = t;
    document.querySelectorAll('[data-tool]').forEach(b => b.classList.toggle('on', b.dataset.tool === t));
    cv.style.cursor = t === 'fill' ? 'cell' : 'crosshair';
  }
  document.querySelectorAll('[data-tool]').forEach(b => b.addEventListener('click', () => setTool(b.dataset.tool)));
  function preview() {
    const pv = document.getElementById('pv');
    pv.style.width = pv.style.height = Math.max(2, size) + 'px';
    pv.style.background = color; pv.style.opacity = opacity;
    document.getElementById('size-v').textContent = size;
    document.getElementById('op-v').textContent = Math.round(opacity * 100) + '%';
  }
  document.getElementById('size').addEventListener('input', e => { size = +e.target.value; preview(); });
  document.getElementById('opacity').addEventListener('input', e => { opacity = e.target.value / 100; preview(); });
  document.getElementById('bg').addEventListener('click', e => {
    const b = e.target.closest('button'); if (!b) return;
    bg = b.dataset.bg;
    [...b.parentNode.children].forEach(x => x.classList.toggle('on', x === b));
    const img = ctx.getImageData(0, 0, cv.width, cv.height); paintBg(); ctx.putImageData(img, 0, 0);
  });
  document.getElementById('undo').addEventListener('click', undo);
  document.getElementById('redo').addEventListener('click', redo);
  document.getElementById('clear').addEventListener('click', () => { saveState(); paintBg(); });
  document.getElementById('save').addEventListener('click', () => {
    // Gabungkan pola latar ke file PNG supaya hasil unduhan sama dengan yang terlihat
    const out = document.createElement('canvas'); out.width = cv.width; out.height = cv.height;
    const o = out.getContext('2d');
    o.fillStyle = '#fff'; o.fillRect(0, 0, out.width, out.height);
    if (bg !== 'plain') {
      o.fillStyle = bg === 'grid' ? '#eceaf3' : '#d4d0e2';
      const s = 24 * DPR;
      for (let x = 0; x < out.width; x += s) for (let y = 0; y < out.height; y += s) {
        if (bg === 'grid') { o.fillRect(x, 0, DPR, out.height); o.fillRect(0, y, out.width, DPR); }
        else { o.beginPath(); o.arc(x + s / 2, y + s / 2, 1.2 * DPR, 0, Math.PI * 2); o.fill(); }
      }
    }
    o.drawImage(cv, 0, 0);
    const a = document.createElement('a');
    a.download = 'coretan-' + new Date().toISOString().slice(0, 10) + '.png';
    a.href = out.toDataURL('image/png'); a.click();
  });
  document.addEventListener('keydown', e => {
    if (e.target.tagName === 'INPUT') return;
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'z') { e.preventDefault(); e.shiftKey ? redo() : undo(); return; }
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'y') { e.preventDefault(); redo(); return; }
    const map = { p: 'pen', m: 'marker', e: 'eraser', l: 'line', r: 'rect', c: 'circle', f: 'fill' };
    if (map[e.key.toLowerCase()] && !e.ctrlKey && !e.metaKey) setTool(map[e.key.toLowerCase()]);
    if (e.key === '[') { size = Math.max(1, size - 2); document.getElementById('size').value = size; preview(); }
    if (e.key === ']') { size = Math.min(60, size + 2); document.getElementById('size').value = size; preview(); }
  });
  let rt;
  window.addEventListener('resize', () => { clearTimeout(rt); rt = setTimeout(fit, 150); });
  fit(); preview();
</script>
</body>
</html>
```

**Cek kebutuhan**
- **Pena** → garis dihaluskan dengan `quadraticCurveTo` melalui titik tengah antarsampel. Dengan stylus, tebal garis mengikuti tekanan (`e.pressure`).
- **Spidol** → setiap gerakan menggambar ulang seluruh goresan dari `snapshot` sebagai satu jalur, jadi warnanya transparan merata dan tidak menumpuk di titik yang sama.
- **Penghapus** → `globalCompositeOperation = 'destination-out'`, sehingga yang terhapus menjadi transparan dan latar tetap terlihat.
- **Garis, kotak, lingkaran** → pratinjau digambar di atas `snapshot` selama pointer bergerak. Tahan Shift untuk kotak dan lingkaran sempurna.
- **Ember cat** → `floodFill()` dengan tumpukan piksel dan toleransi warna kecil.
- **Warna, ukuran, opasitas** → 10 warna siap pakai ditambah `<input type="color">`, slider ukuran 1–60 dan opasitas 10–100%, dengan pratinjau kuas.
- **Undo/redo** → `undoStack` dan `redoStack` berisi `ImageData`, maksimal 30 langkah. Bisa lewat tombol, Ctrl+Z, dan Ctrl+Y.
- **Latar polos/kotak/titik** → kanvas dibiarkan transparan, dan pola latar dipasang lewat CSS `background-image`, jadi mengganti latar tidak mengubah gambar.
- **Simpan PNG** → kanvas sementara digambari latar putih, pola latar yang sama, lalu isi kanvas, sehingga file yang diunduh sama dengan yang terlihat.
- **Mouse, stylus, dan jari** → Pointer Events dengan `setPointerCapture`, dan `touch-action: none` supaya halaman tidak ikut bergulir saat menggambar.

Kanvas memakai `devicePixelRatio` (dibatasi 2) supaya tajam di layar HP, dan gambar dipertahankan saat ukuran jendela berubah. Pintasan alat: P, M, E, L, R, C, F, serta `[` dan `]` untuk ukuran.

Berikut UI chat bernama **Obrolan** dalam satu file HTML. Kontak dan balasannya disimulasikan di browser, tanpa server.

```html
<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Obrolan — Aplikasi Chat</title>
<style>
  :root { --bg: #e7ece9; --side: #ffffff; --chat: #efeae2; --me: #d9fdd3; --them: #ffffff; --text: #111b21; --muted: #667781; --line: #e9edef; --accent: #00a884; }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body { height: 100%; }
  body { font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; background: var(--bg); color: var(--text); overflow: hidden; }
  button, input, textarea { font: inherit; color: inherit; }
  :focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
  .app { height: 100%; max-width: 1400px; margin: 0 auto; display: grid; grid-template-columns: 360px 1fr; background: var(--side); box-shadow: 0 0 30px rgba(0,0,0,.08); }
  .list { border-right: 1px solid var(--line); display: flex; flex-direction: column; min-height: 0; min-width: 0; }
  .list-head { display: flex; justify-content: space-between; align-items: center; padding: 14px 16px; background: #f0f2f5; }
  .list-head h1 { font-size: 1.2rem; }
  .search { padding: 8px 12px; border-bottom: 1px solid var(--line); }
  .search input { width: 100%; border: 0; background: #f0f2f5; padding: 9px 14px; border-radius: 10px; }
  .chats { overflow-y: auto; flex: 1; }
  .contact { display: grid; grid-template-columns: 48px 1fr auto; gap: 12px; align-items: center; padding: 10px 14px; cursor: pointer; border: 0; background: none; width: 100%; text-align: left; border-bottom: 1px solid var(--line); }
  .contact:hover { background: #f5f6f6; }
  .contact.active { background: #f0f2f5; }
  .av { width: 48px; height: 48px; border-radius: 50%; display: grid; place-items: center; font-size: 1.4rem; position: relative; }
  .av.online::after { content: ""; position: absolute; right: 1px; bottom: 1px; width: 12px; height: 12px; border-radius: 50%; background: #25d366; border: 2px solid #fff; }
  .contact .name { font-weight: 600; display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .contact .prev { color: var(--muted); font-size: .88rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; display: block; }
  .contact .meta { text-align: right; font-size: .75rem; color: var(--muted); display: grid; gap: 4px; justify-items: end; }
  .badge { background: var(--accent); color: #fff; border-radius: 999px; min-width: 20px; height: 20px; padding: 0 6px; display: grid; place-items: center; font-weight: 700; font-size: .72rem; }
  .contact > span:nth-child(2) { min-width: 0; }

  .chat { display: flex; flex-direction: column; min-height: 0; min-width: 0; background: var(--chat); background-image: radial-gradient(rgba(0,0,0,.035) 1px, transparent 1px); background-size: 16px 16px; }
  .chat-head { display: flex; align-items: center; gap: 12px; padding: 10px 16px; background: #f0f2f5; border-left: 1px solid var(--line); }
  .chat-head .av { width: 40px; height: 40px; font-size: 1.1rem; }
  .chat-head small { color: var(--muted); display: block; font-size: .8rem; }
  .back { display: none; border: 0; background: none; font-size: 1.4rem; cursor: pointer; width: 34px; }
  .msgs { flex: 1; overflow-y: auto; padding: 16px 6%; display: flex; flex-direction: column; gap: 4px; }
  .day { align-self: center; background: #fff; color: var(--muted); font-size: .75rem; padding: 4px 12px; border-radius: 8px; margin: 10px 0; box-shadow: 0 1px 1px rgba(0,0,0,.06); }
  .msg { max-width: min(75%, 520px); padding: 6px 10px 18px; border-radius: 10px; position: relative; box-shadow: 0 1px 1px rgba(0,0,0,.08); font-size: .95rem; line-height: 1.4; white-space: pre-wrap; overflow-wrap: anywhere; animation: pop .18s ease; min-width: 76px; }
  @keyframes pop { from { transform: scale(.94); opacity: 0; } }
  .msg.me { align-self: flex-end; background: var(--me); border-top-right-radius: 2px; }
  .msg.them { align-self: flex-start; background: var(--them); border-top-left-radius: 2px; }
  .msg time { position: absolute; right: 8px; bottom: 3px; font-size: .68rem; color: var(--muted); }
  .msg .tick { color: #53bdeb; margin-left: 2px; }
  .msg .tick.grey { color: var(--muted); }
  .msg .react { position: absolute; bottom: -12px; left: 8px; background: #fff; border-radius: 999px; padding: 0 5px; font-size: .8rem; box-shadow: 0 1px 2px rgba(0,0,0,.15); }
  .msg.me .react { left: auto; right: 8px; }
  .msg.has-react { margin-bottom: 12px; }
  .typing { align-self: flex-start; background: #fff; border-radius: 10px; padding: 10px 14px; display: none; gap: 4px; }
  .typing.show { display: flex; }
  .typing i { width: 7px; height: 7px; border-radius: 50%; background: #9aa5ac; animation: dot 1.2s infinite; }
  .typing i:nth-child(2) { animation-delay: .2s; } .typing i:nth-child(3) { animation-delay: .4s; }
  @keyframes dot { 30% { transform: translateY(-4px); opacity: 1; } 0%, 60%, 100% { opacity: .5; } }
  .composer { display: flex; gap: 8px; align-items: end; padding: 10px 14px; background: #f0f2f5; position: relative; }
  .composer textarea { flex: 1; resize: none; border: 0; border-radius: 10px; padding: 11px 14px; max-height: 120px; min-height: 44px; background: #fff; line-height: 1.4; min-width: 0; }
  .round { width: 44px; height: 44px; border-radius: 50%; border: 0; background: none; cursor: pointer; font-size: 1.3rem; flex-shrink: 0; }
  .send { background: var(--accent); color: #fff; font-size: 1.05rem; }
  .send:disabled { opacity: .5; cursor: default; }
  .emoji-panel { position: absolute; bottom: 64px; left: 14px; background: #fff; border-radius: 14px; box-shadow: 0 10px 30px rgba(0,0,0,.18); padding: 10px; display: none; grid-template-columns: repeat(8, 36px); gap: 2px; z-index: 5; max-width: calc(100% - 28px); }
  .emoji-panel.open { display: grid; }
  .emoji-panel button { border: 0; background: none; font-size: 1.3rem; cursor: pointer; border-radius: 8px; height: 36px; }
  .emoji-panel button:hover { background: #f0f2f5; }
  .empty { margin: auto; text-align: center; color: var(--muted); padding: 30px; }

  @media (max-width: 760px) {
    .app { grid-template-columns: 1fr; }
    .chat { display: none; }
    .app.in-chat .list { display: none; }
    .app.in-chat .chat { display: flex; }
    .back { display: block; }
    .msgs { padding: 12px 10px; }
    .emoji-panel { grid-template-columns: repeat(7, 36px); }
  }
  @media (prefers-reduced-motion: reduce) { .msg, .typing i { animation: none; } }
</style>
</head>
<body>
<div class="app" id="app">
  <aside class="list">
    <div class="list-head"><h1>Obrolan</h1></div>
    <div class="search"><input id="search" type="search" placeholder="Cari atau mulai obrolan baru" aria-label="Cari kontak"></div>
    <div class="chats" id="chats"></div>
  </aside>
  <section class="chat" id="chat">
    <div class="chat-head">
      <button class="back" id="back" aria-label="Kembali">←</button>
      <div class="av" id="head-av"></div>
      <div><b id="head-name"></b><small id="head-status"></small></div>
    </div>
    <div class="msgs" id="msgs" role="log" aria-live="polite"></div>
    <form class="composer" id="composer">
      <div class="emoji-panel" id="emoji-panel"></div>
      <button type="button" class="round" id="emoji-btn" aria-label="Pilih emoji" aria-expanded="false" aria-controls="emoji-panel">😊</button>
      <textarea id="input" rows="1" placeholder="Ketik pesan" aria-label="Ketik pesan"></textarea>
      <button type="submit" class="round send" id="send" aria-label="Kirim" disabled>➤</button>
    </form>
  </section>
</div>

<script>
  const now = Date.now(), MIN = 6e4;
  const contacts = [
    { id: 'ibu', name: 'Ibu ❤️', av: '👩', bg: '#ffe4e6', online: true, bot: ['Sudah makan belum, Nak?', 'Jangan lupa istirahat ya.', 'Ibu masak opor, pulang kapan?', 'Iya, hati-hati di jalan.'],
      msgs: [{ me: false, t: 'Nak, minggu depan jadi pulang?', at: now - 90 * MIN }, { me: true, t: 'Insyaallah jadi, Bu. Naik kereta Jumat sore.', at: now - 85 * MIN }, { me: false, t: 'Alhamdulillah. Nanti Ibu masakin rendang 😊', at: now - 80 * MIN, react: '❤️' }] },
    { id: 'tim', name: 'Tim Proyek Website', av: '💻', bg: '#dbeafe', online: false, bot: ['Siap, nanti saya cek.', 'Deploy sudah jalan di staging 🚀', 'Meeting jam 2 ya, jangan telat.'],
      msgs: [{ me: false, t: 'Desain halaman checkout sudah final belum?', at: now - 26 * 60 * MIN }, { me: true, t: 'Sudah, link Figma saya kirim sebentar lagi.', at: now - 25 * 60 * MIN }, { me: false, t: 'Oke, besok kita review bareng klien ya', at: now - 40 * MIN }], unread: 2 },
    { id: 'budi', name: 'Budi Santoso', av: '🧑', bg: '#dcfce7', online: true, bot: ['Wkwk iya bener', 'Gas lah 😆', 'Nanti malam futsal jadi?'],
      msgs: [{ me: false, t: 'Bro, nonton timnas Selasa nanti?', at: now - 3 * 60 * MIN }], unread: 1 },
    { id: 'kurir', name: 'Kurir Paket', av: '📦', bg: '#fef3c7', online: false, bot: ['Baik, paket saya titip ke satpam ya.', 'Posisi sudah dekat, 10 menit lagi sampai.'],
      msgs: [{ me: false, t: 'Selamat siang, paket atas nama Kirana sudah di depan gerbang.', at: now - 2 * 24 * 60 * MIN }] }
  ];
  let activeId = null, botTimer;
  const $ = id => document.getElementById(id);
  const hhmm = t => new Date(t).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
  function dayLabel(t) {
    const d = new Date(t);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const diff = Math.round((today - new Date(d.getFullYear(), d.getMonth(), d.getDate())) / 864e5);
    return diff === 0 ? 'Hari ini' : diff === 1 ? 'Kemarin' : d.toLocaleDateString('id-ID', { weekday: diff < 7 ? 'long' : undefined, day: 'numeric', month: 'long' });
  }
  function listTime(t) {
    const label = dayLabel(t);
    if (label === 'Hari ini') return hhmm(t);
    if (label === 'Kemarin') return label;
    return new Date(t).toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit' });
  }

  function renderList() {
    const q = $('search').value.trim().toLowerCase();
    const list = contacts.filter(c => !q || c.name.toLowerCase().includes(q) || c.msgs.some(m => m.t.toLowerCase().includes(q)))
      .sort((a, b) => b.msgs.at(-1).at - a.msgs.at(-1).at);
    $('chats').innerHTML = list.map(c => {
      const last = c.msgs.at(-1);
      return `<button class="contact ${c.id === activeId ? 'active' : ''}" data-id="${c.id}">
        <span class="av ${c.online ? 'online' : ''}" style="background:${c.bg}">${c.av}</span>
        <span><span class="name">${c.name}</span><span class="prev"></span></span>
        <span class="meta"><span>${listTime(last.at)}</span>${c.unread ? `<span class="badge">${c.unread}</span>` : ''}</span></button>`;
    }).join('') || '<p style="padding:20px;color:var(--muted)">Tidak ditemukan.</p>';
    // Isi pesan bisa berasal dari pengguna, jadi dimasukkan lewat textContent.
    $('chats').querySelectorAll('.contact').forEach(b => {
      const last = contacts.find(c => c.id === b.dataset.id).msgs.at(-1);
      b.querySelector('.prev').textContent = (last.me ? '✓✓ ' : '') + last.t;
    });
  }

  function renderChat() {
    const c = contacts.find(x => x.id === activeId);
    if (!c) {
      $('head-av').style.display = 'none';
      $('head-name').textContent = '';
      $('head-status').textContent = '';
      $('msgs').innerHTML = '<p class="empty">💬 Pilih kontak untuk mulai mengobrol.</p>';
      $('composer').style.display = 'none';
      return;
    }
    $('composer').style.display = '';
    $('head-av').style.display = '';
    $('head-av').textContent = c.av;
    $('head-av').style.background = c.bg;
    $('head-name').textContent = c.name;
    $('head-status').textContent = c.online ? 'online' : 'terakhir dilihat ' + listTime(c.msgs.at(-1).at);
    let html = '', lastDay = '';
    c.msgs.forEach((m, i) => {
      const d = dayLabel(m.at);
      if (d !== lastDay) {
        html += `<div class="day">${d}</div>`;
        lastDay = d;
      }
      html += `<div class="msg ${m.me ? 'me' : 'them'} ${m.react ? 'has-react' : ''}" data-i="${i}" title="Klik dua kali untuk memberi reaksi"><span class="text"></span><time>${hhmm(m.at)}${m.me ? `<span class="tick ${m.read ? '' : 'grey'}">✓✓</span>` : ''}</time>${m.react ? `<span class="react">${m.react}</span>` : ''}</div>`;
    });
    html += '<div class="typing" id="typing" aria-hidden="true"><i></i><i></i><i></i></div>';
    $('msgs').innerHTML = html;
    $('msgs').querySelectorAll('.msg').forEach(node => { node.querySelector('.text').textContent = c.msgs[node.dataset.i].t; });
    $('msgs').scrollTop = $('msgs').scrollHeight;
  }

  function open(id) {
    activeId = id;
    const c = contacts.find(x => x.id === id);
    c.unread = 0;
    c.msgs.forEach(m => { if (m.me) m.read = true; });
    $('app').classList.add('in-chat');
    clearTimeout(botTimer);
    renderList();
    renderChat();
    $('input').focus();
  }

  // Salam dibalas salam; selain itu ambil balasan kontak secara bergiliran.
  function pickReply(c, text) {
    if (/halo|hai|pagi|siang|sore|malam/i.test(text)) return `Halo juga! ${c.bot[0]}`;
    return c.bot[c.msgs.length % c.bot.length];
  }

  function send(text) {
    const c = contacts.find(x => x.id === activeId);
    c.msgs.push({ me: true, t: text, at: Date.now(), read: false });
    renderList();
    renderChat();
    // Balasan otomatis: tampilkan "mengetik…" lalu kirim balasan
    clearTimeout(botTimer);
    const replyTo = c.id;
    botTimer = setTimeout(() => {
      if (activeId !== replyTo) return;
      c.msgs.forEach(m => { if (m.me) m.read = true; });
      renderChat();
      $('head-status').textContent = 'sedang mengetik…';
      $('typing').classList.add('show');
      $('msgs').scrollTop = $('msgs').scrollHeight;
      botTimer = setTimeout(() => {
        c.msgs.push({ me: false, t: pickReply(c, text), at: Date.now() });
        if (activeId === replyTo) renderChat();
        else c.unread = (c.unread || 0) + 1;
        renderList();
      }, 1100 + Math.random() * 800);
    }, 600);
  }

  $('chats').addEventListener('click', e => {
    const b = e.target.closest('.contact');
    if (b) open(b.dataset.id);
  });
  $('search').addEventListener('input', renderList);
  $('back').addEventListener('click', () => {
    $('app').classList.remove('in-chat');
    activeId = null;
    renderList();
    renderChat();
  });
  const input = $('input');
  input.addEventListener('input', () => {
    $('send').disabled = !input.value.trim();
    input.style.height = 'auto';
    input.style.height = Math.min(input.scrollHeight, 120) + 'px';
  });
  input.addEventListener('keydown', e => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      $('composer').requestSubmit();
    }
  });
  $('composer').addEventListener('submit', e => {
    e.preventDefault();
    const t = input.value.trim();
    if (!t) return;
    input.value = '';
    input.style.height = 'auto';
    $('send').disabled = true;
    setEmojiPanel(false);
    send(t);
  });
  $('msgs').addEventListener('dblclick', e => {
    const m = e.target.closest('.msg');
    if (!m) return;
    const msg = contacts.find(x => x.id === activeId).msgs[m.dataset.i];
    const cycle = [undefined, '❤️', '👍', '😂'];
    msg.react = cycle[(cycle.indexOf(msg.react) + 1) % cycle.length];
    renderChat();
  });
  const EMOJI = '😀😂🥹😍😘😎🤔😴😭😡👍🙏👏🔥🎉❤️💯🙌🤝✨🍜☕🛵📦🎓💻⚽🌧️'.match(/\p{Extended_Pictographic}️?/gu);
  $('emoji-panel').innerHTML = EMOJI.map(e => `<button type="button">${e}</button>`).join('');
  function setEmojiPanel(open) {
    $('emoji-panel').classList.toggle('open', open);
    $('emoji-btn').setAttribute('aria-expanded', open);
  }
  $('emoji-btn').addEventListener('click', () => setEmojiPanel(!$('emoji-panel').classList.contains('open')));
  $('emoji-panel').addEventListener('click', e => {
    const b = e.target.closest('button');
    if (!b) return;
    const s = input.selectionStart ?? input.value.length;
    input.value = input.value.slice(0, s) + b.textContent + input.value.slice(input.selectionEnd ?? s);
    input.dispatchEvent(new Event('input'));
    input.focus();
  });
  document.addEventListener('click', e => {
    if (!e.target.closest('#emoji-panel, #emoji-btn')) setEmojiPanel(false);
  });
  document.addEventListener('keydown', e => { if (e.key === 'Escape') setEmojiPanel(false); });

  renderList();
  if (matchMedia('(min-width: 761px)').matches) open('ibu'); else renderChat();
</script>
</body>
</html>
```

**Cek kebutuhan**
- **Daftar kontak dengan pencarian** → `renderList()` mengurutkan 4 kontak berdasarkan pesan terbaru. `#search` mencocokkan nama maupun isi pesan.
- **Badge belum dibaca** → setiap kontak punya `unread`. Angkanya hilang saat chat dibuka dengan `open(id)`, dan bertambah jika balasan datang ketika kamu sedang membuka chat lain.
- **Balasan otomatis dengan "sedang mengetik"** → `send()` menandai pesanmu terbaca setelah 600 ms, lalu menampilkan status "sedang mengetik…" dan titik-titik `#typing`. Balasan dari `pickReply()` datang 1,1–1,9 detik kemudian. Sapaan seperti "halo" atau "pagi" dibalas sapaan, pesan lain dibalas bergiliran dari daftar `bot`.
- **Centang dibaca** → pesanmu bertanda ✓✓ abu-abu, lalu berubah biru setelah dibaca.
- **Pemilih emoji** → 28 emoji di `#emoji-panel` disisipkan di posisi kursor. Panel tertutup saat klik di luar, Escape, atau pesan terkirim, dan `aria-expanded` ikut diperbarui.
- **Reaksi pesan** → klik dua kali pada pesan untuk berganti ❤️ → 👍 → 😂 → tanpa reaksi.
- **Tampilan HP** → di bawah 760px halaman dimulai dari daftar kontak, kelas `.in-chat` memindahkan ke ruang chat, dan tombol `#back` kembali.

Isi pesan dipasang dengan `textContent`, jadi teks seperti `<img onerror>` tampil apa adanya. Enter mengirim, Shift+Enter membuat baris baru, kotak ketik membesar sampai 120px, dan `#msgs` memakai `role="log"` supaya pesan baru dibacakan pembaca layar. Pemisah hari ("Hari ini", "Kemarin") dibuat oleh `dayLabel()`.

Berikut game **Pecah Bata** dalam satu file HTML dengan Canvas 2D. Efek suaranya dibuat dengan Web Audio API, jadi tidak ada file audio.

```html
<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Pecah Bata — Game Arkade</title>
<style>
  :root { --bg: #0b1026; --panel: #141b3d; --text: #eef1ff; --muted: #8e97c7; --accent: #ffcc33; --mono: ui-monospace, Menlo, Consolas, monospace; }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; background: radial-gradient(circle at 50% 0%, #1f2a66, var(--bg) 60%); color: var(--text); min-height: 100vh; display: flex; flex-direction: column; align-items: center; padding: 16px; }
  button { font: inherit; color: inherit; border: 0; cursor: pointer; }
  button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
  .hud, .stage, .bar { width: min(720px, 100%); }
  .hud { display: flex; justify-content: space-between; align-items: center; gap: 10px; margin-bottom: 10px; }
  .title, .overlay h1, .stat b { font-family: var(--mono); font-weight: 400; }
  .title { font-size: clamp(.8rem, 3vw, 1.1rem); }
  .title span, .overlay h1 span { color: var(--accent); }
  .stats { display: flex; gap: 6px; }
  .stat { background: var(--panel); border-radius: 10px; padding: 4px 10px; text-align: center; min-width: 58px; }
  .stat small { display: block; font-size: .62rem; text-transform: uppercase; letter-spacing: .1em; color: var(--muted); }
  .stat b { font-size: .75rem; }
  .stage { position: relative; aspect-ratio: 3 / 4; max-height: calc(100vh - 150px); }
  @media (min-width: 700px) { .stage { aspect-ratio: 4 / 3; } }
  canvas { width: 100%; height: 100%; display: block; border-radius: 16px; background: linear-gradient(#10173a, #0a0f27); box-shadow: 0 0 0 2px #26306a; touch-action: none; }
  .overlay { position: absolute; inset: 0; display: flex; flex-direction: column; justify-content: center; align-items: center; gap: 12px; padding: 20px; text-align: center; border-radius: 16px; background: rgba(8, 11, 30, .8); }
  .overlay[hidden] { display: none; }
  .overlay h1 { font-size: clamp(1.4rem, 6vw, 2.4rem); line-height: 1.3; }
  .overlay p, .keys, .legend { color: var(--muted); }
  .overlay p { max-width: 380px; }
  .btn { background: var(--accent); color: #2a1d00; border-radius: 12px; padding: 12px 26px; font-weight: 800; }
  .keys, .legend { font-size: .85rem; }
  .legend { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; list-style: none; }
  .legend i { display: inline-block; width: 12px; height: 12px; border-radius: 3px; margin-right: 4px; }
  .bar { display: flex; justify-content: space-between; gap: 8px; margin-top: 10px; }
  .bar button { background: var(--panel); border-radius: 10px; padding: 8px 14px; color: var(--muted); }
</style>
</head>
<body>
<header class="hud">
  <div class="title" aria-hidden="true">PECAH <span>BATA</span></div>
  <div class="stats">
    <div class="stat"><small>Skor</small><b id="score">0</b></div>
    <div class="stat"><small>Level</small><b id="level">1</b></div>
    <div class="stat"><small>Nyawa</small><b id="lives">❤❤❤</b></div>
  </div>
</header>
<main class="stage">
  <canvas id="game" role="img" aria-label="Area permainan Pecah Bata"></canvas>
  <div class="overlay" id="overlay">
    <h1>PECAH <span>BATA</span></h1>
    <p id="ov-text" aria-live="polite">Pantulkan bola, hancurkan semua bata, dan kumpulkan power-up. Skor tertinggi: <b id="hi">0</b></p>
    <button class="btn" id="start">▶ Mulai</button>
    <ul class="legend">
      <li><i style="background:#4ade80"></i>Papan lebar</li>
      <li><i style="background:#60a5fa"></i>Multi-bola</li>
      <li><i style="background:#f472b6"></i>Bola lambat</li>
      <li><i style="background:#facc15"></i>+1 nyawa</li>
    </ul>
    <p class="keys">Mouse/jari untuk menggerakkan · ← → atau A D · Spasi untuk meluncurkan · P untuk jeda</p>
  </div>
</main>
<div class="bar">
  <button id="pause">⏸ Jeda</button>
  <button id="sound" aria-pressed="true">🔊 Suara</button>
</div>

<script>
  const cv = document.getElementById('game'), g = cv.getContext('2d');
  const $ = id => document.getElementById(id);
  const FONT = 'ui-monospace, Menlo, Consolas, monospace';
  const COLORS = ['#f87171', '#fb923c', '#facc15', '#4ade80', '#38bdf8', '#a78bfa'];
  const POWERS = { wide: '#4ade80', multi: '#60a5fa', slow: '#f472b6', life: '#facc15' };
  const ICONS = { wide: '↔', multi: '•••', slow: '⏬', life: '♥' };
  // Pola level: angka = jumlah pukulan untuk memecah bata, 0 = kosong
  const LEVELS = [
    ['1111111111', '1111111111', '1111111111', '1111111111', '1111111111'],
    ['0022222200', '0211111120', '2111111112', '2112112112', '0211111120', '0022222200'],
    ['3030303030', '0303030303', '2222222222', '1111111111', '2020202020', '0101010101'],
    ['3333333333', '3000000003', '3022222203', '3021111203', '3022222203', '3000000003', '3333333333']
  ];
  let W, H, scale;
  let state = 'menu', score = 0, lives = 3, level = 0, bricks = [], balls = [], drops = [];
  let paddle = { x: 0, w: 0, target: null }, wideUntil = 0, slowUntil = 0, keys = {}, sound = true, hi = 0;
  try { hi = +localStorage.getItem('pecah-hi') || 0; } catch (e) {}
  $('hi').textContent = hi;

  function resize() {
    const r = cv.getBoundingClientRect();
    const dpr = Math.min(devicePixelRatio || 1, 2);
    cv.width = r.width * dpr;
    cv.height = r.height * dpr;
    W = r.width;
    H = r.height;
    scale = W / 600;
    g.setTransform(dpr, 0, 0, dpr, 0, 0);
    layoutBricks();
    paddle.x = Math.min(Math.max(paddle.x || W / 2, 0), W);
  }

  function layoutBricks() {
    const cols = 10, pad = 6 * scale, top = 60 * scale;
    const bw = (W - pad * (cols + 1)) / cols, bh = Math.max(14, 22 * scale);
    bricks.forEach(b => Object.assign(b, { x: pad + b.c * (bw + pad), y: top + b.r * (bh + pad), w: bw, h: bh }));
  }
  function loadLevel(n) {
    // Setelah level 4 pola diulang dengan bata yang lebih kuat
    const map = LEVELS[n % LEVELS.length], bonus = Math.floor(n / LEVELS.length);
    bricks = [];
    map.forEach((row, r) => [...row].forEach((ch, c) => {
      const hp = Math.min(+ch + bonus, 4);
      if (+ch) bricks.push({ r, c, hp, max: hp });
    }));
    layoutBricks();
    drops = [];
    resetBall();
    $('level').textContent = n + 1;
  }
  const paddleW = () => (performance.now() < wideUntil ? 150 : 96) * scale;
  const ballSpeed = () => (5.2 + level * .5) * scale * (performance.now() < slowUntil ? .6 : 1);
  function resetBall() {
    balls = [{ x: paddle.x, y: H - 40 * scale, vx: 0, vy: 0, stuck: true, r: Math.max(5, 7 * scale) }];
  }
  function launch() {
    balls.filter(b => b.stuck).forEach(b => {
      const a = -Math.PI / 2 + (Math.random() - .5) * .8;
      b.vx = Math.cos(a);
      b.vy = Math.sin(a);
      b.stuck = false;
    });
  }

  // Efek suara Web Audio; AudioContext dibuat setelah interaksi pertama
  let actx;
  function beep(freq, dur = .06, type = 'square') {
    if (!sound || !actx) return;
    const osc = actx.createOscillator(), vol = actx.createGain(), t = actx.currentTime;
    osc.type = type;
    osc.frequency.value = freq;
    vol.gain.setValueAtTime(.06, t);
    vol.gain.exponentialRampToValueAtTime(.001, t + dur);
    osc.connect(vol).connect(actx.destination);
    osc.start();
    osc.stop(t + dur);
  }

  function start() {
    if (!actx) {
      try { actx = new AudioContext(); } catch (e) {}
    }
    if (state === 'won') loadLevel(++level);
    else { score = 0; lives = 3; level = 0; loadLevel(0); }
    state = 'play';
    $('overlay').hidden = true;
    updateHud();
  }
  function showOverlay(title, accent, text, btn) {
    $('overlay').hidden = false;
    $('overlay').querySelector('h1').innerHTML = `${title} <span>${accent}</span>`;
    $('ov-text').textContent = text;
    $('start').textContent = btn;
  }
  function updateHud() {
    $('score').textContent = score;
    $('lives').textContent = lives > 0 ? '❤'.repeat(Math.min(lives, 5)) + (lives > 5 ? '+' : '') : '—';
    if (score > hi) {
      hi = score;
      try { localStorage.setItem('pecah-hi', hi); } catch (e) {}
    }
  }

  function hitBrick(b) {
    for (const br of bricks) {
      if (br.hp <= 0) continue;
      // Titik terdekat pada bata ke pusat bola
      const cx = Math.max(br.x, Math.min(b.x, br.x + br.w)), cy = Math.max(br.y, Math.min(b.y, br.y + br.h));
      if ((b.x - cx) ** 2 + (b.y - cy) ** 2 > b.r * b.r) continue;
      const overlapX = Math.min(b.x + b.r - br.x, br.x + br.w - (b.x - b.r));
      const overlapY = Math.min(b.y + b.r - br.y, br.y + br.h - (b.y - b.r));
      if (overlapX < overlapY) b.vx = b.x < br.x + br.w / 2 ? -Math.abs(b.vx) : Math.abs(b.vx);
      else b.vy = b.y < br.y + br.h / 2 ? -Math.abs(b.vy) : Math.abs(b.vy);
      br.hp--;
      score += 10 * (level + 1);
      beep(440 + br.hp * 120);
      if (br.hp <= 0 && Math.random() < .14) {
        const types = Object.keys(POWERS);
        drops.push({ x: br.x + br.w / 2, y: br.y, type: types[Math.floor(Math.random() * types.length)] });
      }
      updateHud();
      return;
    }
  }

  function applyPower(type) {
    beep(660, .12, 'sine');
    if (type === 'wide') wideUntil = performance.now() + 12000;
    if (type === 'slow') slowUntil = performance.now() + 8000;
    if (type === 'life') { lives++; updateHud(); }
    if (type === 'multi') {
      const src = balls.find(b => !b.stuck) || balls[0];
      for (const off of [-.5, .5]) {
        const a = Math.atan2(src.vy || -1, src.vx) + off;
        balls.push({ x: src.x, y: src.y, vx: Math.cos(a), vy: Math.sin(a), stuck: false, r: src.r });
      }
    }
  }

  function update(dt) {
    // Papan mengikuti pointer atau tombol panah
    paddle.w = paddleW();
    if (keys.left) paddle.x -= 9 * scale * dt;
    if (keys.right) paddle.x += 9 * scale * dt;
    if (paddle.target !== null) paddle.x += (paddle.target - paddle.x) * Math.min(1, .35 * dt);
    paddle.x = Math.min(Math.max(paddle.x, paddle.w / 2), W - paddle.w / 2);
    const py = H - 28 * scale, ph = Math.max(10, 12 * scale);

    balls.forEach(b => {
      if (b.stuck) {
        b.x = paddle.x;
        b.y = py - b.r - 1;
        return;
      }
      // Gerak dipecah jadi langkah kecil supaya bola cepat tidak menembus bata
      const sp = ballSpeed(), steps = Math.ceil(sp * dt / (b.r * .8));
      for (let s = 0; s < steps; s++) {
        b.x += b.vx * sp * dt / steps;
        b.y += b.vy * sp * dt / steps;
        if (b.x < b.r) {
          b.x = b.r;
          b.vx = Math.abs(b.vx);
          beep(300);
        }
        if (b.x > W - b.r) {
          b.x = W - b.r;
          b.vx = -Math.abs(b.vx);
          beep(300);
        }
        if (b.y < b.r) {
          b.y = b.r;
          b.vy = Math.abs(b.vy);
          beep(300);
        }
        // Sudut pantulan ditentukan titik kena pada papan
        if (b.vy > 0 && b.y + b.r >= py && b.y + b.r <= py + ph + b.vy * sp && Math.abs(b.x - paddle.x) <= paddle.w / 2 + b.r) {
          const a = -Math.PI / 2 + (b.x - paddle.x) / (paddle.w / 2) * Math.PI / 3;
          b.vx = Math.cos(a);
          b.vy = Math.sin(a);
          b.y = py - b.r;
          beep(220, .05, 'triangle');
        }
        hitBrick(b);
      }
      if (b.y - b.r > H) b.dead = true;
    });
    balls = balls.filter(b => !b.dead);
    if (!balls.length) {
      lives--;
      updateHud();
      beep(110, .3, 'sawtooth');
      if (lives <= 0) {
        state = 'over';
        showOverlay('GAME', 'OVER', `Skor kamu ${score}. Skor tertinggi: ${hi}`, '↻ Main Lagi');
        return;
      }
      resetBall();
    }

    drops.forEach(d => {
      d.y += 2.6 * scale * dt;
      if (d.y > py - 8 && d.y < py + ph && Math.abs(d.x - paddle.x) < paddle.w / 2 + 10) {
        d.got = true;
        applyPower(d.type);
      }
    });
    drops = drops.filter(d => !d.got && d.y < H + 20);

    if (bricks.every(b => b.hp <= 0)) {
      state = 'won';
      score += lives * 100;
      updateHud();
      showOverlay(`LEVEL ${level + 1}`, 'SELESAI!', `Bonus nyawa +${lives * 100}. Skor: ${score}`, '▶ Level Berikutnya');
    }
  }

  function text(str, x, y, size, color) {
    g.fillStyle = color;
    g.font = `${size}px ${FONT}`;
    g.textAlign = 'center';
    g.textBaseline = 'middle';
    g.fillText(str, x, y);
  }
  function draw() {
    const now = performance.now(), s = Math.max(scale, .8);
    g.clearRect(0, 0, W, H);
    bricks.forEach(b => {
      if (b.hp <= 0) return;
      g.fillStyle = COLORS[b.r % COLORS.length];
      g.globalAlpha = .45 + .55 * b.hp / b.max;
      g.beginPath();
      g.roundRect(b.x, b.y, b.w, b.h, 4);
      g.fill();
      g.globalAlpha = 1;
      if (b.max > 1) text(b.hp, b.x + b.w / 2, b.y + b.h / 2 + 1, Math.max(10, 12 * scale), 'rgba(0,0,0,.4)');
    });
    drops.forEach(d => {
      g.fillStyle = POWERS[d.type];
      g.beginPath();
      g.arc(d.x, d.y, 9 * s, 0, Math.PI * 2);
      g.fill();
      text(ICONS[d.type], d.x, d.y + 1, 11 * s, '#0b1026');
    });

    const py = H - 28 * scale, ph = Math.max(10, 12 * scale);
    g.fillStyle = now < wideUntil ? '#4ade80' : '#fbbf24';
    g.beginPath();
    g.roundRect(paddle.x - paddle.w / 2, py, paddle.w, ph, ph / 2);
    g.fill();
    g.fillStyle = now < slowUntil ? '#f472b6' : '#fff';
    balls.forEach(b => {
      g.beginPath();
      g.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      g.fill();
    });

    if (state === 'play' && balls.some(b => b.stuck)) {
      text('Klik / ketuk / Spasi untuk meluncurkan', W / 2, H * .62, Math.max(11, 14 * scale), 'rgba(238,241,255,.7)');
    }
    if (state === 'paused') {
      g.fillStyle = 'rgba(8,11,30,.6)';
      g.fillRect(0, 0, W, H);
      text('JEDA', W / 2, H / 2, 28 * s, '#fff');
    }
  }

  let last = performance.now();
  function loop(now) {
    const dt = Math.min((now - last) / 16.67, 3);
    last = now;
    if (state === 'play') update(dt);
    draw();
    requestAnimationFrame(loop);
  }

  function togglePause() {
    if (state === 'play') state = 'paused';
    else if (state === 'paused') state = 'play';
    $('pause').textContent = state === 'paused' ? '▶ Lanjut' : '⏸ Jeda';
  }
  const toX = e => e.clientX - cv.getBoundingClientRect().left;
  cv.addEventListener('pointermove', e => { paddle.target = toX(e); });
  cv.addEventListener('pointerdown', e => {
    paddle.target = toX(e);
    if (state === 'play') launch();
  });
  function setKey(e, down) {
    const k = e.key.toLowerCase();
    if (k === 'arrowleft' || k === 'a') keys.left = down;
    else if (k === 'arrowright' || k === 'd') keys.right = down;
    else return;
    paddle.target = null;
  }
  document.addEventListener('keydown', e => {
    setKey(e, true);
    const k = e.key.toLowerCase();
    if (e.code === 'Space') {
      e.preventDefault();
      if (state === 'play') launch();
      else if (!$('overlay').hidden) start();
    } else if (k === 'p' || k === 'escape') {
      togglePause();
    }
  });
  document.addEventListener('keyup', e => setKey(e, false));
  $('start').addEventListener('click', start);
  $('pause').addEventListener('click', togglePause);
  $('sound').addEventListener('click', e => {
    sound = !sound;
    e.currentTarget.textContent = sound ? '🔊 Suara' : '🔇 Bisu';
    e.currentTarget.setAttribute('aria-pressed', sound);
  });
  document.addEventListener('visibilitychange', () => { if (document.hidden && state === 'play') togglePause(); });
  window.addEventListener('resize', resize);
  resize();
  loadLevel(0);
  requestAnimationFrame(loop);
</script>
</body>
</html>
```

**Cek kebutuhan**
- **4 level dengan pola berbeda** → `LEVELS` berisi grid 10 kolom berupa teks angka: barisan rata, belah ketupat, papan catur, dan kotak berdinding. Setelah level 4, `loadLevel()` mengulang pola dengan kekuatan bata +1 per putaran, maksimal 4.
- **Bata yang dipukul berkali-kali** → angka di pola adalah jumlah pukulan. Bata memudar saat nyawanya berkurang, dan sisa nyawanya ditampilkan sebagai angka.
- **Power-up** → `applyPower()` menangani empat jenis yang jatuh dengan peluang 14% dari bata yang pecah: paddle melebar 12 detik, 2 bola tambahan, bola melambat ×0,6 selama 8 detik, dan +1 nyawa.
- **Efek suara tanpa file** → `beep()` membuat nada pendek dengan oscillator. Pantulan dinding, paddle, bata, power-up, dan kehilangan nyawa masing-masing punya nada sendiri. `AudioContext` baru dibuat saat permainan dimulai, dan tombol `#sound` mematikan suara.
- **Skor tertinggi tersimpan** → setiap pukulan bernilai 10 × level, dan sisa nyawa menjadi bonus saat level selesai. Skor tertinggi disimpan di `localStorage` di dalam `try/catch`.
- **Mouse, keyboard, sentuhan** → paddle mengikuti pointer, termasuk sentuhan, dengan `touch-action: none`. Panah atau A/D menggerakkan paddle, Spasi meluncurkan bola, dan P atau Esc menjeda. Permainan juga berhenti otomatis saat tab disembunyikan.

Gerak bola dibagi menjadi beberapa sub-langkah per frame supaya bola cepat tidak menembus bata. Sudut pantulan bergantung pada titik kena di paddle, maksimal ±60°.

Cara yang paling sering dipakai adalah **serakah**: ambil pecahan terbesar sebanyak mungkin, lalu lanjut ke pecahan berikutnya. Untuk pecahan Rupiah standar cara ini memang benar. Tapi karena daftar pecahannya bisa diatur, serakah bisa salah. Contohnya nominal 6 dengan pecahan [1, 3, 4]: serakah menghasilkan 4 + 1 + 1 (3 keping), padahal 3 + 3 hanya 2 keping.

Jadi saya pakai **dynamic programming**. `keping[i]` menyimpan jumlah keping minimal untuk nominal `i`, dihitung dari nominal yang lebih kecil, lalu kombinasinya direkonstruksi dari pecahan terakhir yang dipakai. Ada beberapa hal lain yang ditangani:

- **Ukuran tabel.** Tabel sepanjang nominal bisa besar untuk jutaan rupiah. Karena semua pecahan Rupiah kelipatan 100, nominal dan pecahan dibagi dulu dengan FPB-nya, sehingga tabelnya 100 kali lebih kecil.
- **Nominal yang tidak bisa dibentuk** mengembalikan `None`, misalnya Rp150 dengan pecahan terkecil Rp100.
- **Input `float` ditolak.** Uang dihitung dalam bilangan bulat rupiah, supaya tidak ada sisa pembagian seperti 0,30000000000000004.

```python
from math import gcd


def pecahan_minimal(jumlah, pecahan):
    """Kombinasi {pecahan: banyaknya} dengan total keping paling sedikit, atau None jika tidak bisa dibentuk."""
    if not all(isinstance(x, int) and not isinstance(x, bool) for x in [jumlah, *pecahan]):
        raise TypeError("jumlah dan pecahan harus bilangan bulat (rupiah, bukan float)")
    if jumlah < 0 or not pecahan or any(p <= 0 for p in pecahan):
        raise ValueError("jumlah harus >= 0 dan setiap pecahan harus > 0")
    pecahan = sorted(set(pecahan))
    # Semua pecahan Rupiah kelipatan 100: bagi dengan FPB supaya tabel 100x lebih kecil.
    fpb = gcd(*pecahan)
    if jumlah % fpb:
        return None
    n, satuan = jumlah // fpb, [p // fpb for p in pecahan]
    TAK_TERHINGGA = n + 1
    keping = [0] + [TAK_TERHINGGA] * n   # keping[i] = jumlah keping minimal untuk nominal i
    terakhir = [0] * (n + 1)             # pecahan terakhir yang dipakai, untuk merekonstruksi jawaban
    for i in range(1, n + 1):
        for s in satuan:
            if s > i:
                break
            if keping[i - s] + 1 < keping[i]:
                keping[i], terakhir[i] = keping[i - s] + 1, s
    if keping[n] == TAK_TERHINGGA:
        return None
    hasil = {}
    while n:
        hasil[terakhir[n] * fpb] = hasil.get(terakhir[n] * fpb, 0) + 1
        n -= terakhir[n]
    return dict(sorted(hasil.items(), reverse=True))


def serakah(jumlah, pecahan):
    """Ambil pecahan terbesar dulu. Benar untuk pecahan Rupiah, tapi tidak untuk sembarang pecahan."""
    hasil = {}
    for p in sorted(pecahan, reverse=True):
        if jumlah >= p:
            hasil[p], jumlah = divmod(jumlah, p)
    return hasil if jumlah == 0 else None


if __name__ == "__main__":
    rupiah = [100, 200, 500, 1000, 2000, 5000, 10000, 20000, 50000, 100000]
    print("Rp87.300:", pecahan_minimal(87_300, rupiah))
    print("Rp0:", pecahan_minimal(0, rupiah))
    print("Rp150 dengan pecahan Rupiah:", pecahan_minimal(150, rupiah))
    print("6 dengan [1, 3, 4]  serakah:", serakah(6, [1, 3, 4]), " minimal:", pecahan_minimal(6, [1, 3, 4]))
    print("7 dengan [2, 4]:", pecahan_minimal(7, [2, 4]))
    print("Rp9.999.900:", sum(pecahan_minimal(9_999_900, rupiah).values()), "keping")
    try:
        pecahan_minimal(1000.5, rupiah)
    except TypeError as e:
        print("TypeError:", e)
